// PREENCHA SOMENTE ESTES 3 VALORES.
// Não envie as chaves na conversa.
return [{
  json: {
    evolutionBaseUrl: 'https://evolution.vectradev.shop',
    evolutionInstance: 'miranda-express',

    supabaseUrl: 'https://qudpndluldjudukelwxd.supabase.co',

    page: 1,
    limit: 1000
  }
}];

const config = $('Configuração Geral').first().json;
let raw = $input.first()?.json ?? {};

function decodeStreamResponse(value) {
  if (!value || typeof value !== 'object') return value;

  const buffers =
    value?._readableState?.buffer ??
    value?.body?._readableState?.buffer ??
    null;

  if (!Array.isArray(buffers) || !buffers.length) return value;

  const bytes = [];
  for (const part of buffers) {
    const data = part?.data ?? part?.chunk?.data;
    if (Array.isArray(data)) bytes.push(...data);
  }

  if (!bytes.length) return value;

  const text = Buffer.from(bytes).toString('utf8');
  return JSON.parse(text);
}

raw = decodeStreamResponse(raw);

function findArray(value, depth = 0) {
  if (depth > 10 || value == null) return [];
  if (Array.isArray(value)) return value;
  if (typeof value !== 'object') return [];

  if (Array.isArray(value?.messages?.records)) return value.messages.records;

  for (const key of ['records', 'messages', 'data', 'items', 'rows']) {
    const child = value?.[key];
    if (Array.isArray(child)) return child;
    if (child && typeof child === 'object') {
      const found = findArray(child, depth + 1);
      if (found.length) return found;
    }
  }

  for (const child of Object.values(value)) {
    const found = findArray(child, depth + 1);
    if (found.length) return found;
  }

  return [];
}

function messageText(item) {
  const message = item?.message ?? item?.data?.message ?? {};
  return (
    message?.conversation ??
    message?.extendedTextMessage?.text ??
    message?.imageMessage?.caption ??
    message?.videoMessage?.caption ??
    item?.text ??
    item?.body ??
    item?.messageText ??
    ''
  );
}

function timestampToIso(value) {
  if (!value) return null;
  const n = Number(value);

  if (!Number.isNaN(n)) {
    const ms = n < 1000000000000 ? n * 1000 : n;
    const d = new Date(ms);
    return Number.isNaN(d.getTime()) ? null : d.toISOString();
  }

  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

const records = findArray(raw);
const output = [];

for (const item of records) {
  if (!item || typeof item !== 'object') continue;

  const key =
    item?.key && typeof item.key === 'object'
      ? item.key
      : item?.data?.key && typeof item.data.key === 'object'
        ? item.data.key
        : {};

  const remoteJid = String(
    key?.remoteJid ??
    item?.remoteJidAlt ??
    item?.remoteJid ??
    item?.data?.remoteJid ??
    ''
  );

  const fromMe = Boolean(
    key?.fromMe ??
    item?.fromMe ??
    item?.data?.fromMe ??
    false
  );

  const isGroup = remoteJid.endsWith('@g.us');
  const text = String(messageText(item)).trim();

  if (!remoteJid || isGroup || !text) continue;

  const customerNumber = remoteJid
    .replace('@s.whatsapp.net', '')
    .replace('@c.us', '')
    .replace('@lid', '')
    .replace(/\D/g, '');

  let customerName = String(
    item?.pushName ??
    item?.data?.pushName ??
    item?.notifyName ??
    item?.senderName ??
    'Cliente'
  ).trim();

  if (
    !customerName ||
    ['sobre', 'about', 'undefined', 'null', 'você'].includes(customerName.toLowerCase())
  ) {
    customerName = 'Cliente';
  }

  const messageId = String(
    key?.id ??
    item?.messageId ??
    item?.data?.messageId ??
    item?.id ??
    ''
  ).trim();

  const timestamp = timestampToIso(
    item?.messageTimestamp ??
    item?.data?.messageTimestamp ??
    item?.timestamp ??
    item?.createdAt
  );

  output.push({
    json: {
      supabaseUrl: config.supabaseUrl,

      instance_name: 'miranda-express',
      message_id:
        messageId ||
        `${remoteJid}-${timestamp || Date.now()}-${Math.random().toString(36).slice(2)}`,
      remote_jid: remoteJid,
      customer_number: customerNumber,
      customer_name: customerName,
      message_text: text.slice(0, 5000),
      message_type: String(item?.messageType ?? item?.data?.messageType ?? 'text'),
      from_me: fromMe,
      is_group: false,
      message_timestamp: timestamp,
      analyzed: false
    }
  });
}

if (!output.length) {
  throw new Error(
    `Nenhuma mensagem válida encontrada. Registros detectados: ${records.length}`
  );
}

return output;

const input = $input.all().map(item => item.json);

// Remove mensagens repetidas antes do UPSERT.
// A Evolution pode devolver o mesmo message_id mais de uma vez por causa
// de atualizações de status, sincronização e cópias do histórico.
const uniqueByMessageId = new Map();

for (const message of input) {
  const id = String(message.message_id ?? '').trim();
  if (!id) continue;

  // Mantém a versão mais recente encontrada para cada message_id.
  uniqueByMessageId.set(id, message);
}

const uniqueMessages = [...uniqueByMessageId.values()];
const batchSize = 25;
const output = [];

for (let i = 0; i < uniqueMessages.length; i += batchSize) {
  const slice = uniqueMessages.slice(i, i + batchSize);

  output.push({
    json: {
      supabaseUrl: slice[0].supabaseUrl,
      batch_number: Math.floor(i / batchSize) + 1,
      batch_size: slice.length,
      total_unique_messages: uniqueMessages.length,
      messages: slice.map(m => ({
        instance_name: m.instance_name,
        message_id: m.message_id,
        remote_jid: m.remote_jid || null,
        customer_number: m.customer_number || null,
        customer_name: m.customer_name || 'Cliente',
        message_text: m.message_text,
        message_type: m.message_type || 'text',
        from_me: Boolean(m.from_me),
        is_group: Boolean(m.is_group),
        message_timestamp: m.message_timestamp || null,
        analyzed: Boolean(m.analyzed)
      }))
    }
  });
}

if (!output.length) {
  throw new Error('Nenhuma mensagem única válida foi encontrada para importar.');
}

return output;

const originalRows = $('Normalizar Mensagens').all().map(i => i.json);

const categories = [
  { category: 'entrega', regex: /entrega|frete|taxa|bairro|cidade|localiza|bel[eé]m|ananindeua|icoaraci/i },
  { category: 'originalidade', regex: /original|primeira linha|importado|fabricante|marca/i },
  { category: 'compatibilidade', regex: /compat[ií]vel|funciona|serve|xiaomi|redmi|iphone|samsung|note|modelo/i },
  { category: 'preço', regex: /pre[cç]o|valor|quanto|custa/i },
  { category: 'estoque', regex: /tem|dispon[ií]vel|estoque|acabou/i },
  { category: 'pagamento', regex: /pix|dinheiro|cart[aã]o|parcela|pagamento/i },
  { category: 'garantia', regex: /garantia|defeito|troca/i },
  { category: 'cabo', regex: /cabo|lightning|usb|tipo c|type-c/i }
];

const groups = new Map();

for (const row of originalRows) {
  if (row.from_me) continue;

  const text = String(row.message_text ?? '').trim();
  if (!text) continue;

  let category = 'outros';
  for (const rule of categories) {
    if (rule.regex.test(text)) {
      category = rule.category;
      break;
    }
  }

  if (!groups.has(category)) groups.set(category, []);
  groups.get(category).push(text);
}

const config = $('Configuração Geral').first().json;
const output = [];

for (const [category, questions] of groups.entries()) {
  const unique = [...new Set(questions)].slice(0, 20);
  if (!unique.length) continue;

  output.push({
    json: {
      supabaseUrl: config.supabaseUrl,
      category,
      intent: category,
      question_example: unique[0],
      approved_answer:
        'PENDENTE DE REVISÃO — analise as perguntas desta categoria antes de ativar esta resposta.',
      keywords: [...new Set(
        unique
          .join(' ')
          .toLowerCase()
          .normalize('NFD')
          .replace(/[\u0300-\u036f]/g, '')
          .split(/\W+/)
          .filter(w => w.length >= 4)
      )].slice(0, 30),
      source_message_count: questions.length,
      active: false
    }
  });
}

return output;

