const root = $json.body ?? $json ?? {};
const payload =
  root.data?.data ??
  root.data ??
  root.message ??
  root;

const key =
  payload.key ??
  payload.message?.key ??
  root.key ??
  root.data?.key ??
  {};

const message =
  payload.message?.message ??
  payload.message ??
  root.message?.message ??
  root.message ??
  {};

let remoteJid = String(
  key.remoteJid ??
  payload.remoteJid ??
  payload.remote_jid ??
  root.remoteJid ??
  root.remote_jid ??
  ''
);

const remoteJidAlt = String(
  key.remoteJidAlt ??
  payload.remoteJidAlt ??
  root.remoteJidAlt ??
  ''
);

if (remoteJid.endsWith('@lid') && remoteJidAlt) {
  remoteJid = remoteJidAlt;
}

const extractText = value => String(
  value?.conversation ??
  value?.extendedTextMessage?.text ??
  value?.imageMessage?.caption ??
  value?.videoMessage?.caption ??
  value?.documentMessage?.caption ??
  value?.buttonsResponseMessage?.selectedDisplayText ??
  value?.listResponseMessage?.title ??
  ''
).trim();

const text = String(
  extractText(message) ||
  payload.text ||
  payload.body ||
  root.text ||
  ''
).trim();

const imageMessage =
  message?.imageMessage ??
  payload?.imageMessage ??
  payload?.message?.imageMessage ??
  null;

const videoMessage =
  message?.videoMessage ??
  payload?.videoMessage ??
  payload?.message?.videoMessage ??
  null;

const documentMessage =
  message?.documentMessage ??
  payload?.documentMessage ??
  payload?.message?.documentMessage ??
  null;

const audioMessage =
  message?.audioMessage ??
  payload?.audioMessage ??
  payload?.message?.audioMessage ??
  null;

const declaredMessageType = String(
  payload?.messageType ??
  payload?.message_type ??
  root?.messageType ??
  root?.data?.messageType ??
  ''
).trim();

const hasImageMedia = Boolean(
  imageMessage ||
  /^(image|imageMessage)$/i.test(declaredMessageType)
);

const hasMedia = Boolean(
  hasImageMedia ||
  videoMessage ||
  documentMessage ||
  audioMessage ||
  /^(video|videoMessage|document|documentMessage|audio|audioMessage)$/i.test(declaredMessageType)
);

const mediaType =
  hasImageMedia ? 'image' :
  videoMessage || /^(video|videoMessage)$/i.test(declaredMessageType) ? 'video' :
  documentMessage || /^(document|documentMessage)$/i.test(declaredMessageType) ? 'document' :
  audioMessage || /^(audio|audioMessage)$/i.test(declaredMessageType) ? 'audio' :
  null;

const mediaMimeType = String(
  imageMessage?.mimetype ??
  imageMessage?.mime_type ??
  videoMessage?.mimetype ??
  videoMessage?.mime_type ??
  documentMessage?.mimetype ??
  documentMessage?.mime_type ??
  audioMessage?.mimetype ??
  audioMessage?.mime_type ??
  ''
).trim() || null;

// Contexto de resposta/citação do WhatsApp.
const contextInfo =
  message.extendedTextMessage?.contextInfo ??
  message.imageMessage?.contextInfo ??
  message.videoMessage?.contextInfo ??
  message.documentMessage?.contextInfo ??
  payload.contextInfo ??
  root.contextInfo ??
  {};

const quotedMessage = contextInfo?.quotedMessage ?? {};
const quotedText = extractText(quotedMessage);
const quotedParticipant = String(
  contextInfo?.participant ??
  contextInfo?.remoteJid ??
  ''
).trim();

const number = remoteJid
  .replace(/@(s\.whatsapp\.net|c\.us|lid)$/i, '')
  .replace(/\D/g, '');

const fromMeRaw =
  key.fromMe ??
  payload.fromMe ??
  payload.from_me ??
  payload.message?.key?.fromMe ??
  root.fromMe ??
  root.from_me ??
  root.data?.fromMe ??
  root.data?.from_me ??
  false;

const fromMe =
  fromMeRaw === true ||
  fromMeRaw === 1 ||
  String(fromMeRaw).toLowerCase() === 'true';

const isGroup = remoteJid.endsWith('@g.us');

let customerName = String(
  payload.pushName ??
  payload.notifyName ??
  root.pushName ??
  root.notifyName ??
  'Cliente'
).trim() || 'Cliente';

if (/^(undefined|null|sobre|about|você|voce)$/i.test(customerName)) {
  customerName = 'Cliente';
}

const messageId = String(
  key.id ??
  payload.messageId ??
  payload.message_id ??
  root.messageId ??
  root.message_id ??
  `${number}-${Date.now()}`
).trim();

const eventName = String(
  root.event ??
  root.eventType ??
  root.type ??
  ''
).trim();

const normalizedEventName = eventName
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '_');

const isTechnicalSendMessageEvent =
  normalizedEventName === 'send_message' ||
  normalizedEventName.endsWith('_send_message') ||
  normalizedEventName.includes('send_message');

return [{
  json: {
    instance:
      root.instance ??
      root.instanceName ??
      payload.instance ??
      'miranda-express',

    event: eventName || null,
    remoteJid,
    number,
    customerName,
    messageId,
    text,
    originalText: text,
    quotedText,
    quotedParticipant: quotedParticipant || null,
    hasQuotedMessage: Boolean(quotedText),
    fromMe,
    isGroup,

    hasMedia,
    hasImageMedia,
    mediaType,
    mediaMimeType,
    declaredMessageType: declaredMessageType || null,

    // V25.6: imagem sem legenda é uma mensagem válida.
    shouldProcess:
      !isGroup &&
      !isTechnicalSendMessageEvent &&
      Boolean(number) &&
      (fromMe || Boolean(text) || hasMedia),

    debug_from_me_raw: fromMeRaw
  }
}];

const c = $('Configuração Geral1').first().json;

const sr = $('Buscar Sessão').first().json;

// v23.9.4: normaliza qualquer formato de resposta do HTTP Request do Supabase
// e escolhe sempre a sessão mais recentemente atualizada.
const decodeStreamResponse = value => {
  if (!value || typeof value !== 'object') return value;

  const buffers =
    value?._readableState?.buffer ??
    value?.body?._readableState?.buffer ??
    value?.data?._readableState?.buffer ??
    null;

  if (!Array.isArray(buffers) || buffers.length === 0) return value;

  const bytes = [];
  for (const part of buffers) {
    const data = part?.data ?? part?.chunk?.data ?? part?.buffer?.data ?? null;
    if (Array.isArray(data)) bytes.push(...data);
  }

  if (!bytes.length) return value;

  const text = Buffer.from(bytes).toString('utf8').trim();
  if (!text) return [];

  try {
    return JSON.parse(text);
  } catch {
    return value;
  }
};

const collectSessionRows = (value, rows = [], depth = 0) => {
  if (depth > 10 || value === null || value === undefined) return rows;

  const decoded = decodeStreamResponse(value);
  if (decoded !== value) return collectSessionRows(decoded, rows, depth + 1);

  if (Array.isArray(value)) {
    for (const item of value) collectSessionRows(item, rows, depth + 1);
    return rows;
  }

  if (typeof value !== 'object') return rows;

  if (value.customer_number) rows.push(value);

  for (const key of ['body', 'data', 'result', 'results', 'rows', 'response']) {
    if (value[key] !== undefined) collectSessionRows(value[key], rows, depth + 1);
  }

  return rows;
};

const sessionRows = collectSessionRows(sr)
  .filter(row => String(row.customer_number ?? '') === String(c.number ?? ''))
  .sort((a, b) => {
    const ta = Date.parse(a.updated_at ?? '') || 0;
    const tb = Date.parse(b.updated_at ?? '') || 0;
    return tb - ta;
  });

const s = sessionRows[0] ?? {};

// IMPORTANTE:
// Usa .all() para receber todos os itens retornados pelo node Consultar Produtos.
// Antes, o uso de .first() fazia o catálogo receber apenas o primeiro produto.
const productItems = $('Consultar Produtos').all();

const rawProducts = productItems.flatMap(item => {
  const value = item.json;

  if (Array.isArray(value)) {
    return value;
  }

  if (Array.isArray(value?.data)) {
    return value.data;
  }

  if (
    value &&
    typeof value === 'object' &&
    Object.keys(value).length > 0
  ) {
    return [value];
  }

  return [];
});

const normalizeArray = value => {
  if (Array.isArray(value)) {
    return value
      .map(item => String(item).trim())
      .filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    return value
      .split(/[,;|]/)
      .map(item => item.trim())
      .filter(Boolean);
  }

  return [];
};

// O painel/Supabase é a única fonte oficial.
// Campos ausentes permanecem null.
// A IA não pode completar dados usando conhecimento próprio.
const products = rawProducts
  .map(p => {
    const inventory = Array.isArray(p.inventories)
      ? (p.inventories[0] ?? {})
      : (p.inventories ?? {});

    const metadata =
      p.metadata &&
      typeof p.metadata === 'object' &&
      !Array.isArray(p.metadata)
        ? p.metadata
        : {};

    const physical = Number(
      inventory.physical_quantity ??
      p.physical_quantity ??
      p.stock_quantity ??
      p.available_quantity ??
      0
    );

    const reserved = Number(
      inventory.reserved_quantity ??
      p.reserved_quantity ??
      0
    );

    const available = Math.max(
      0,
      physical - reserved
    );

    return {
      product_id:
        p.id ??
        p.product_id ??
        null,

      inventory_id:
        inventory.id ??
        p.inventory_id ??
        null,

      product_name:
        p.name ??
        p.product_name ??
        null,

      product_slug:
        p.slug ??
        p.product_slug ??
        null,

      description:
        p.description ??
        null,

      brand:
        metadata.brand ??
        metadata.marca ??
        null,

      model:
        metadata.model ??
        metadata.modelo ??
        null,

      power_watts:
        p.power_watts ??
        metadata.power_watts ??
        null,

      connector_type:
        p.connector_type ??
        metadata.connector_type ??
        null,

      cable_included:
        metadata.cable_included ??
        metadata.cabo_incluso ??
        null,

      compatibility: normalizeArray(
        metadata.compatibility ??
        metadata.compatible_with ??
        metadata.compatibilidade
      ),

      incompatibility: normalizeArray(
        metadata.incompatibility ??
        metadata.not_compatible_with ??
        metadata.incompatibilidade
      ),

      aliases: [...new Set([
        ...normalizeArray(
          metadata.aliases ??
          metadata.keywords ??
          metadata.palavras_chave
        ),
        ...(Array.isArray(p.product_aliases)
          ? p.product_aliases
              .filter(row => row?.is_active !== false && row?.alias)
              .map(row => String(row.alias).trim())
          : [])
      ].filter(Boolean))],

      faqs: Array.isArray(p.product_faqs)
        ? p.product_faqs
            .filter(row => row?.active !== false && row?.approved_answer)
            .map(row => ({
              intent_key: row.intent_key ?? null,
              question_examples: normalizeArray(row.question_examples),
              keywords: normalizeArray(row.keywords),
              approved_answer: String(row.approved_answer).trim(),
              short_answer: row.short_answer ? String(row.short_answer).trim() : null,
              priority: Number(row.priority ?? 100)
            }))
        : [],

      warranty_days:
        p.warranty_days ??
        metadata.warranty_days ??
        null,

      sale_price:
        Number(p.sale_price ?? 0),

      is_active:
        p.is_active !== false,

      physical_quantity:
        physical,

      reserved_quantity:
        reserved,

      available_quantity:
        available
    };
  })
  .filter(product =>
    product.product_id &&
    product.product_name &&
    product.is_active === true &&
    product.available_quantity > 0
  );


const compatibilityItems = $('Buscar Compatibilidade de Celulares').all();

// ======================================================
// BASE MESTRE V1.2 — ADAPTADOR RPC -> FORMATO LEGADO
// Mantém o contrato que o restante da V25.6.2 já conhece.
// ======================================================
const masterRaw = compatibilityItems
  .map(item => item?.json)
  .find(value => value && typeof value === 'object' && !Array.isArray(value)) ?? {};

const deviceMasterResolution =
  masterRaw && typeof masterRaw === 'object'
    ? masterRaw
    : {};

const masterDevice =
  deviceMasterResolution.device && typeof deviceMasterResolution.device === 'object'
    ? deviceMasterResolution.device
    : {};

const masterProducts = Array.isArray(deviceMasterResolution.products)
  ? deviceMasterResolution.products
  : [];

const compatibilityCatalog =
  deviceMasterResolution.status === 'RESOLVED'
    ? masterProducts
        .map(p => ({
          device_model_id:
            deviceMasterResolution.device_model_id ??
            masterDevice.device_model_id ??
            null,
          product_id: p.product_id ?? null,
          product_name: p.product_name ?? null,
          brand: masterDevice.brand ?? null,
          model: masterDevice.model ?? null,
          aliases: Array.isArray(masterDevice.aliases) ? masterDevice.aliases : [],
          connector_type: masterDevice.connector_type ?? p.connector_type ?? null,
          official_max_watts: masterDevice.official_max_watts ?? null,
          official_protocols: Array.isArray(masterDevice.official_protocols)
            ? masterDevice.official_protocols
            : [],
          charging_supported: p.charging_supported ?? null,
          fast_charging_possible: p.fast_charging_possible ?? null,
          full_power_guaranteed: p.full_power_guaranteed ?? null,
          compatibility_level: p.compatibility_level ?? null,
          approved_answer: p.approved_answer ?? null,
          notes: p.notes ?? null,
          sale_price: p.sale_price ?? null,
          power_watts: p.power_watts ?? null,
          available_quantity: p.available_quantity ?? 0,
          commercial_priority: p.commercial_priority ?? null,
          source: 'base_mestre_rpc_v1_2'
        }))
        .filter(row =>
          row.product_id &&
          row.brand &&
          row.model &&
          row.approved_answer
        )
    : [];

const kb = $("Buscar Conhecimento")
  .all()
  .flatMap(item => {
    if (Array.isArray(item.json)) {
      return item.json;
    }

    if (
      !item.json ||
      typeof item.json !== 'object' ||
      Object.keys(item.json).length === 0
    ) {
      return [];
    }

    if (Array.isArray(item.json.data)) {
      return item.json.data;
    }

    return [item.json];
  })
  .filter(item =>
    item &&
    typeof item === 'object' &&
    (
      item.approved_answer ||
      item.category
    )
  );

const pendingField =
  !s.product_id ? 'produto' :
  !Number(s.quantity ?? 0) ? 'quantidade' :
  !s.customer_name ? 'nome' :
  !s.neighborhood ? 'bairro' :
  !s.address ? 'endereço' :
  !s.payment_method ? 'pagamento' :
  (s.delivery_fee === null || s.delivery_fee === undefined)
    ? 'taxa de entrega'
    : 'confirmação';

const currentMessage = String(c.text ?? "").trim();

const normalizedMessage = currentMessage
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .trim();

// ======================================================
// V25.9 — CONTEXTO ENXUTO PARA OPENAI
// Evita enviar sessão histórica gigante, KB inteira
// e catálogo completo de compatibilidade em toda chamada.
// ======================================================

const normalizeSearch = value => String(value ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Sessão segura: preserva os campos transacionais,
// mas impede last_bot_message/last_customer_message gigantes.
const safeSession = {
  ...s
};

const originalLastBot = String(safeSession.last_bot_message ?? '').trim();
if (originalLastBot.length > 900) {
  safeSession.last_bot_message =
    'Resposta anterior extensa omitida para controle de contexto.';
}

const originalLastCustomer = String(
  safeSession.last_customer_message ?? ''
).trim();

if (originalLastCustomer.length > 1800) {
  safeSession.last_customer_message =
    originalLastCustomer.slice(-1800);
}

// Contexto usado SOMENTE para escolher compatibilidades relevantes.
const compatibilitySearchContext = normalizeSearch([
  currentMessage,
  c.quotedText,
  safeSession.device_brand,
  safeSession.device_model,
  safeSession.product_name,
  safeSession.last_customer_message
].filter(Boolean).join(' '));

// Pontua registros de compatibilidade.
// Modelos/aliases exatos têm prioridade.
const scoredCompatibility = compatibilityCatalog
  .map(row => {
    const brand = normalizeSearch(row?.brand);
    const model = normalizeSearch(row?.model);
    const aliases = Array.isArray(row?.aliases)
      ? row.aliases.map(normalizeSearch).filter(Boolean)
      : [];

    let score = 0;

    if (brand && compatibilitySearchContext.includes(brand)) {
      score += 25;
    }

    if (model && compatibilitySearchContext.includes(model)) {
      score += 120;
    }

    for (const alias of aliases) {
      if (alias && compatibilitySearchContext.includes(alias)) {
        score = Math.max(score, 130);
      }
    }

    const modelTokens = model
      .split(' ')
      .filter(token => token.length >= 2);

    const hits = modelTokens.filter(
      token => compatibilitySearchContext.includes(token)
    ).length;

    score = Math.max(score, hits * 20);

    if (
      safeSession.product_id &&
      String(row?.product_id ?? '') === String(safeSession.product_id)
    ) {
      score += 10;
    }

    return { row, score };
  })
  .filter(item => item.score >= 40)
  .sort((a, b) => b.score - a.score);

// No prompt entram no máximo 6 compatibilidades.
// Se não houver correspondência, a base vai vazia.
const relevantCompatibilityCatalog = scoredCompatibility
  .slice(0, 6)
  .map(item => ({
    product_id: item.row.product_id ?? null,
    product_name: item.row.product_name ?? null,
    brand: item.row.brand ?? null,
    model: item.row.model ?? null,
    aliases: Array.isArray(item.row.aliases)
