    fast_charging_possible: item.row.fast_charging_possible ?? null,
    full_power_guaranteed: item.row.full_power_guaranteed ?? null,
    compatibility_level: item.row.compatibility_level ?? null,
    approved_answer: item.row.approved_answer ?? null
  }));

// KB geral: remove entradas de compatibilidade já cobertas acima
