          faq.approved_answer.trim()
        )
        .slice(0, 20)
        .map(faq => ({
          intent_key: faq.intent_key ?? null,
          question_examples: Array.isArray(faq.question_examples)
            ? faq.question_examples
            : [],
          keywords: Array.isArray(faq.keywords)
            ? faq.keywords
            : [],
          approved_answer: faq.approved_answer.trim(),
          short_answer: faq.short_answer ?? null,
          priority: Number(faq.priority ?? 100)
        }))
    : [],
  warranty_days: product.warranty_days ?? null,
  sale_price: product.sale_price ?? null,
  available_quantity: product.available_quantity ?? 0
}));

const conversation = {
  context: "conversation",
  intent: "other",
  messageRole: "other",
  pauseCheckout: false,
  confidence: 1
};

// ... regras ...
