else if (/\b(serve|funciona|compat|compativel|compatível|tipo\s*c|type\s*c|usb|usb-c|lightning|micro\s*usb|entrada|conector|redmi|xiaomi|samsung|galaxy|iphone|motorola|moto|note)\b/i.test(normalizedMessage)) {

