else if (/\b(original|garantia|bivolt|anatel|homologado|marca|esquenta|aquece|superaquece|queima|danifica|estraga|prejudica|seguro|watts?|potencia|potência|turbo|carrega|carregamento|bateria|cabo|acompanha)\b/i.test(normalizedMessage)) {

