    .test(normalizedMessage)

) {

  conversation.intent = "payment_question";

}
// ========================================
// STATE MACHINE V25
// ========================================

const state = {
  pauseCheckout: conversation.pauseCheckout,
  keepSession: true,
  resumeCheckout: false,
  action: "continue"
};

switch (conversation.intent) {

  case "technical_question":
  case "compatibility_question":
  case "delivery_question":
    state.pauseCheckout = true;
    state.action = "answer_question";
    break;

  case "new_order":
    state.keepSession = false;
    state.action = "restart_order";
    break;

  case "thanks":
    state.action = "social_reply";
    break;

  default:
    state.action = "continue";
}// ========================================
// ACTION ENGINE V25
// ========================================

const actions = {

  updateSession: true,
  updateProduct: true,
  updateQuantity: true,
  updatePayment: true,
  updateAddress: true,
  createOrder: true

};

switch (state.action) {

  case "answer_question":

    actions.updateSession = false;
    actions.updateProduct = false;
    actions.updateQuantity = false;
    actions.updatePayment = false;
    actions.updateAddress = false;
    actions.createOrder = false;

    break;

  case "restart_order":

    actions.updateSession = true;

    break;

  case "social_reply":

    actions.updateSession = false;
    actions.createOrder = false;

    break;

  default:
    break;
}
