const extractDeviceSearch = text => {
  let value = normalizeDeviceText(text)
    .replace(/^(?:e um|e uma|e|eh|meu celular e|meu aparelho e|o modelo e|modelo e)\s+/, '')
    .trim();

  const reverseSamsung = value.match(/^([asmxg]\d{1,3}(?:\s*[45]g)?)\s+(?:samsung|galaxy)$/);
  if (reverseSamsung) {
    value = `samsung ${reverseSamsung[1]}`;
  }

  value = value
    .replace(/\b(?:quero|preciso|gostaria|serve|funciona|compativel|compatível|carrega|carregar|usar|carregador|carregadores|turbo|modelo|celular|telefone|aparelho|pra|para|pro|no|na|meu|minha|um|uma|o|a|de|do|da|isso|esse|essa|sim|correto|exato)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (modelOnlyDevice && previousBotDeviceSearch) {
    const previousCore = previousBotDeviceSearch.match(/\b([asmxg]\d{1,3}(?:\s*[45]g)?|g\d{1,3}(?:\s*[45]g)?)\b/)?.[1] ?? '';
    if (!value || value === previousCore || currentDeviceText === previousCore) {
      return previousBotDeviceSearch;
    }
  }

  if (!value && contextualDeviceConfirmation && previousBotDeviceSearch) {
    return previousBotDeviceSearch;
  }

  return value || previousBotDeviceSearch;
};

const scoreCompatibilityRow = (row, search) => {
  const normalizedSearch = normalizeDeviceText(search);
  if (!normalizedSearch) return 0;

  const brand = normalizeDeviceText(row.brand);
  const model = normalizeDeviceText(row.model);
  const aliases = Array.isArray(row.aliases)
    ? row.aliases.map(normalizeDeviceText).filter(Boolean)
    : [];

  if (!model) return 0;

  const brandMatch = Boolean(brand && normalizedSearch.includes(brand));
  const modelCoreTokens = model
    .split(' ')
    .filter(token => token.length >= 2 && /\d/.test(token));
  const coreHits = modelCoreTokens
    .filter(token => normalizedSearch.includes(token))
    .length;

  let score = brandMatch ? 20 : 0;

  if (model === normalizedSearch || normalizedSearch.includes(model)) {
    score = Math.max(score, 105);
  }

  for (const alias of aliases) {
    if (alias === normalizedSearch || normalizedSearch.includes(alias)) {
      score = Math.max(score, 115);
    }
  }

  // Marca sozinha nunca identifica aparelho. Exige o núcleo do modelo (A06, G75, X6...).
  if (modelCoreTokens.length && coreHits === modelCoreTokens.length) {
    score = Math.max(score, brandMatch ? 100 : 85);
  } else if (coreHits > 0) {
    score = Math.max(score, (brandMatch ? 20 : 0) + coreHits * 35);
  }

  return score;
};

const formatWarranty = days => {
  const value = Number(days);

  if (!Number.isFinite(value) || value <= 0) return null;
  if (value === 30) return '30 dias';
  if (value === 60) return '60 dias';
  if (value === 90) return '3 meses';
  if (value === 180) return '6 meses';
  if (value === 365) return '1 ano';

  return `${value} dias`;
};

