    }
  }];
}

// Palavras soltas usadas apenas para manter a conversa.
// Não registra interesse e não força catálogo.
if (isCasualFiller) {
  reply = 'Pode falar, estou acompanhando.';
  state.last_bot_message = reply;

  return [{
    json: {
      ...b,
      state,
      reply,
      detectedQuantity,
      createOrder: false,
      registerProductInterest: false,
      conversationIntent: 'casual_filler',
      preserveCurrentReply: true
    }
  }];
}

// Comparação comercial direta entre 67W e 120W.
// Evita transformar uma dúvida simples em interrogatório ou busca ambígua de produto.
const comparisonContext = normalize([old.last_customer_message, old.last_bot_message, currentOriginal].filter(Boolean).join(' '));
const asks67vs120Comparison =
  /\b67\s*w\b/.test(comparisonContext) &&
  /\b120\s*w\b/.test(comparisonContext) &&
  /\b(diferenca|comparar|comparacao|aplicacao|especifique os dois|qual e melhor|entre os dois)\b/.test(normalize(currentOriginal));

if (asks67vs120Comparison) {
  const p67 = products.find(p => Number(p.power_watts ?? 0) === 67 || /\b67\s*w\b/i.test(String(p.product_name ?? '')));
  const p120 = products.find(p => Number(p.power_watts ?? 0) === 120 || /\b120\s*w\b/i.test(String(p.product_name ?? '')));
  const mentionsA34 = /\b(?:samsung|galaxy)?\s*a\s*34(?:\s*5\s*g)?\b/.test(normalizeDeviceText(comparisonContext));
  const price67 = p67 ? ` por R$ ${money(p67.sale_price)}` : '';
  const price120 = p120 ? ` por R$ ${money(p120.sale_price)}` : '';

  let stockNotice = '';
  if (!p67 && p120) stockNotice = ' O 67W está sem estoque no momento; o 120W está disponível.';
  else if (p67 && !p120) stockNotice = ' O 120W está sem estoque no momento; o 67W está disponível.';
  else if (!p67 && !p120) stockNotice = ' No momento, nenhum dos dois aparece disponível no estoque.';

  const practicalAdvice = mentionsA34
    ? (p67
        ? 'No Samsung Galaxy A34 5G, o aparelho aceita até 25W e limita automaticamente a potência. O 67W já é suficiente; o 120W só faz mais sentido para uso também em aparelhos mais potentes.'
        : p120
          ? 'No Samsung Galaxy A34 5G, o aparelho aceita até 25W e limita automaticamente a potência. O 120W pode ser usado, mas o celular não receberá 120W.'
          : 'No Samsung Galaxy A34 5G, o aparelho aceita até 25W e limita automaticamente a potência.')
    : 'O celular recebe somente a potência que suporta; uma fonte mais potente não força carga acima do limite do aparelho.';

  reply = `A diferença principal é a capacidade da fonte: o 67W${price67} atende a maioria dos celulares, enquanto o 120W${price120} oferece mais reserva de potência.${stockNotice} ${practicalAdvice}`.trim();
  state.last_bot_message = reply;

  return [{
    json: {
      ...b,
      state,
      reply,
      detectedQuantity,
      createOrder: false,
      registerProductInterest: false,
      conversationIntent: 'comparison_67w_120w',
      preserveCurrentReply: true
    }
  }];
}

// V25.6.2 — compatibilidade precisa terminar em oportunidade de venda, não em interrogatório.
const buildCompatibilitySalesReply = (baseAnswer, searchValue, selectedProductId = null) => {
  const answer = String(baseAnswer ?? '').trim();
  const search = normalizeDeviceText(searchValue);
  if (!search) return answer;

  const matchingRows = compatibilityCatalog
    .map(row => ({ row, score: scoreCompatibilityRow(row, search) }))
    .filter(item => item.score >= 55)
    .sort((a, b) => b.score - a.score);

  const compatibleProductIds = new Set(
    matchingRows.map(item => String(item.row.product_id ?? '')).filter(Boolean)
  );

  const availableCompatible = products.filter(product =>
    Number(product.available_quantity ?? 0) > 0 &&
    compatibleProductIds.has(String(product.product_id ?? ''))
  );

  let preferred = selectedProductId
    ? availableCompatible.find(product => String(product.product_id) === String(selectedProductId))
    : null;

  if (!preferred) {
    preferred =
      availableCompatible.find(product => Number(product.power_watts ?? 0) === 67) ||
      availableCompatible.find(product => Number(product.power_watts ?? 0) === 120) ||
      availableCompatible.sort((a, b) => Number(a.sale_price ?? 0) - Number(b.sale_price ?? 0))[0] ||
      null;
  }

  if (!preferred) return answer;

  const preferredRow = matchingRows.find(item =>
    String(item.row.product_id ?? '') === String(preferred.product_id ?? '')
  )?.row ?? null;

  const factual = String(preferredRow?.approved_answer ?? answer).trim();
  if (/\bquer(?: que eu)?(?: separe| reservar)?\b.*\bunidade|\bquantas unidades\b/i.test(factual)) {
    return factual;
  }

  const cta = selectedProductId
    ? `Quer que eu separe 1 unidade do ${preferred.product_name} por R$ ${money(preferred.sale_price)}?`
    : `Para o seu aparelho, eu indicaria o ${preferred.product_name} por R$ ${money(preferred.sale_price)}. Quer 1 unidade?`;

  return `${factual}\n\n${cta}`.trim();
};

// Pergunta de compatibilidade com celular.
// Frases como "pra sansung A15" significam aparelho de destino, não produto fora do catálogo.
if (hasDeviceCompatibilityIntent) {
  const engineCompatibility =
    b.compatibility && typeof b.compatibility === 'object'
      ? b.compatibility
      : {};

  if (
    engineCompatibility.found === true &&
    String(engineCompatibility.answer ?? '').trim()
  ) {
    const engineSearch = normalizeDeviceText([
      engineCompatibility.device_brand,
      engineCompatibility.device_model,
      engineCompatibility.device
    ].filter(Boolean).join(' '));

    const resolvedOptions = Array.isArray(engineCompatibility.compatible_products)
      ? engineCompatibility.compatible_products.filter(product =>
          product &&
          product.product_id &&
          Number(product.available_quantity ?? 0) > 0
        )
      : [];

    const selectedCompatibilityProductId = old.product_id || ai.product_id || null;

    reply = !selectedCompatibilityProductId && resolvedOptions.length > 1
      ? String(engineCompatibility.answer).trim()
      : buildCompatibilitySalesReply(
          String(engineCompatibility.answer).trim(),
          engineSearch,
          selectedCompatibilityProductId
        );

    state.device_brand =
      engineCompatibility.device_brand ??
      state.device_brand ??
      null;
    state.device_model =
      engineCompatibility.device_model ??
      engineCompatibility.device ??
      state.device_model ??
      null;
    state.device_connector =
      engineCompatibility.device_connector ??
      state.device_connector ??
      null;
    state.compatibility_status = normalizeSessionCompatibilityStatus(
      engineCompatibility.session_status ?? engineCompatibility.compatibility_status,
      true
    );

    state.last_bot_message = reply;

    return [{
      json: {
        ...b,
        state,
        reply,
        detectedQuantity,
        createOrder: false,
        registerProductInterest: false,
        conversationIntent: 'device_compatibility',
        deviceSearch: state.device_model,
        preserveCurrentReply: true
      }
    }];
  }

  let deviceSearch = extractDeviceSearch(currentOriginal);

  // Se a resposta atual for curta ("mais rápido no meu iPhone", "esse serve?")
  // reutiliza o modelo já salvo ou presente na mensagem citada.
  if (
    !deviceSearch ||
    /^(?:iphone|samsung|xiaomi|redmi|poco|motorola|moto|apple)$/.test(deviceSearch)
  ) {
    deviceSearch =
      extractDeviceSearch(quotedOriginal) ||
      normalizeDeviceText(old.device_model ?? '') ||
      deviceSearch;
  }

  const rankedCompatibility = compatibilityCatalog
    .map(row => ({
      row,
      score: scoreCompatibilityRow(row, deviceSearch)
    }))
    .filter(item => item.score > 0)
    .sort((a, z) => z.score - a.score);

  const strongMatches = rankedCompatibility.filter(item =>
    item.score >= 55 &&
    (!rankedCompatibility[1] || item.score >= rankedCompatibility[0].score - 10)
  );

  const selectedProductId =
    old.product_id ||
    ai.product_id ||
    null;

  const productSpecificMatches = selectedProductId
    ? strongMatches.filter(item =>
        String(item.row.product_id) === String(selectedProductId)
      )
    : strongMatches;

  const usableMatches =
    productSpecificMatches.length > 0
      ? productSpecificMatches
      : strongMatches;

  if (usableMatches.length > 0) {
    const uniqueAnswers = [
      ...new Set(
        usableMatches
          .map(item => String(item.row.approved_answer ?? '').trim())
          .filter(Boolean)
      )
    ];

    if (uniqueAnswers.length === 1) {
      reply = uniqueAnswers[0];
    } else if (selectedProductId) {
      reply =
        uniqueAnswers[0] ||
        'Encontrei esse aparelho na base, mas preciso confirmar a resposta técnica desse carregador.';
    } else {
      const matchedProducts = usableMatches
        .map(item => {
          const product = products.find(p =>
            String(p.product_id) === String(item.row.product_id)
          );

          return product && item.row.approved_answer
            ? `• ${product.product_name}: ${item.row.approved_answer}`
            : null;
        })
        .filter(Boolean);

      reply = matchedProducts.length
        ? `${matchedProducts.join('\n')}`
        : uniqueAnswers[0] || 'Encontrei o aparelho e vou apresentar as opções compatíveis disponíveis.';
    }

    reply = buildCompatibilitySalesReply(
      reply,
      deviceSearch,
      selectedProductId
    );

    // V26 — persiste exatamente as opções mostradas, na mesma ordem.
    if (!selectedProductId) {
      const compatibleIds = new Set(
        usableMatches.map(item => String(item.row.product_id ?? '')).filter(Boolean)
      );
      const v26Options = products
        .filter(product =>
          Number(product.available_quantity ?? 0) > 0 &&
          compatibleIds.has(String(product.product_id ?? ''))
        )
        .map(product => ({
          product_id: product.product_id,
          product_slug: product.product_slug ?? null,
          product_name: product.product_name,
          sale_price: Number(product.sale_price),
          inventory_id: product.inventory_id ?? null,
          power_watts: product.power_watts ?? null
        }));

      if (v26Options.length) {
        state.product_key = null; state.product_id = null; state.product_name = null;
        state.unit_price = null; state.inventory_id = null; state.quantity = null;
        state.neighborhood = null; state.address = null; state.reference = null;
        state.payment_method = null; state.delivery_fee = null;
        state.order_id = null; state.order_number = null; state.status = 'collecting';
        state.checkout_phase = 'choosing_product';
        state.product_options = v26Options;
        state.transaction_version = 'v26';
        reply = `Sim, temos opções compatíveis:\n` +
          v26Options.map((product, index) =>
            `${index + 1}. ${product.product_name} — R$ ${v26Money(product.sale_price)}`
          ).join('\n') +
          `\n\nQual opção você prefere?`;
      }
    }

  } else {
    const mentionsSamsungA34 =
      /\b(?:samsung|galaxy)?\s*a34(?:\s*5g)?\b/.test(normalizedDeviceMessage);
    const mentionsSamsungA15 =
      /\b(?:samsung|galaxy)?\s*a15(?:\s*[45]g)?\b/.test(normalizedDeviceMessage);
    const variantAlreadyAnswered = /\b[45]g\b/.test(normalizedDeviceMessage);
    const targetProduct = selectedProductId
      ? products.find(p => String(p.product_id) === String(selectedProductId))
      : null;

    if (mentionsSamsungA34) {
      const p67Available = products.find(p => Number(p.power_watts ?? 0) === 67 || /\b67\s*w\b/i.test(String(p.product_name ?? '')));
      const p120Available = products.find(p => Number(p.power_watts ?? 0) === 120 || /\b120\s*w\b/i.test(String(p.product_name ?? '')));
      const targetLabel = targetProduct?.product_name ?? (p67Available?.product_name || p120Available?.product_name || 'carregador');

      let salesContinuation = 'Se quiser seguir, me diga qual carregador você prefere.';
      if (targetProduct) {
        salesContinuation = `Se quiser seguir com o ${targetLabel}, me diga quantas unidades.`;
      } else if (p67Available) {
        salesContinuation = `O 67W está disponível por R$ ${money(p67Available.sale_price)} e já atende bem esse aparelho. Quer uma unidade?`;
      } else if (p120Available) {
        salesContinuation = `O 67W está sem estoque no momento. O 120W está disponível por R$ ${money(p120Available.sale_price)}; quer seguir com ele?`;
      }

      reply =
        `Sim. O ${targetLabel} pode ser usado no Samsung Galaxy A34 5G com cabo USB-C compatível. ` +
        `O aparelho aceita carga rápida de até 25W e puxa somente a potência que suporta, sem receber 67W ou 120W à força. ` +
        salesContinuation;
    } else if (mentionsSamsungA15 && !variantAlreadyAnswered) {
      reply = 'Você está falando do Samsung Galaxy A15. Me confirma apenas se é 4G ou 5G para eu orientar corretamente.';
    } else if (mentionsSamsungA15 && variantAlreadyAnswered) {
      reply = 'Perfeito, entendi a versão informada. Vou consultar as opções compatíveis disponíveis.';
    } else if (standaloneDeviceModel || contextualDeviceConfirmation || String(ai.intent ?? '') === 'compatibility_question') {
      const detectedDevice =
        deviceSearch ||
        previousBotDeviceSearch ||
        currentOriginal
          .replace(/^(?:ele (?:é|e) compat[ií]vel com (?:meu )?celular|meu celular (?:é|e)|meu aparelho (?:é|e))\s*/i, '')
          .replace(/[?!.]+$/g, '')
          .trim() ||
        'esse aparelho';

      const detectedNorm = normalizeDeviceText(detectedDevice);
      if (/\bsamsung\b/.test(detectedNorm)) {
        state.device_brand = 'Samsung';
        const core = detectedNorm.match(/\b([asmxg]\d{1,3}(?:\s*[45]g)?)\b/)?.[1] ?? null;
        if (core) state.device_model = `Galaxy ${core.toUpperCase().replace('5G', '5G').replace('4G', '4G')}`;
      }

      reply =
        `Entendi o aparelho: ${state.device_brand && state.device_model ? `${state.device_brand} ${state.device_model}` : detectedDevice}. ` +
        `Esse modelo ainda não está cadastrado na nossa base de compatibilidade. Não precisa repetir o modelo; vou confirmar a opção correta para não te indicar errado.`;
    } else {
      reply = 'Claro. Me diga a marca e o modelo do celular que eu verifico para você.';
    }
  }

  state.last_bot_message = reply;

  return [{
    json: {
      ...b,
      state,
      reply,
      detectedQuantity,
      createOrder: false,
      registerProductInterest: false,
      conversationIntent: 'device_compatibility',
      deviceSearch,
      preserveCurrentReply: true
    }
  }];
}

// Pergunta sobre garantia.
// Nunca trata "garantia" como nome de produto fora do catálogo.
if (asksWarranty) {
  const previousProduct =
    old.product_id
      ? products.find(p => String(p.product_id) === String(old.product_id))
      : null;

  const targetProduct = selected || previousProduct || null;

  if (targetProduct) {
    const warrantyText = formatWarranty(targetProduct.warranty_days);

    reply = warrantyText
      ? `O ${targetProduct.product_name} possui ${warrantyText} de garantia contra defeito de fabricação. A garantia não cobre danos por mau uso, queda, umidade ou alterações no produto.`
      : `A garantia do ${targetProduct.product_name} ainda não está informada no cadastro. Vou confirmar o prazo correto antes de passar essa informação.`;
  } else {
    const productsWithWarranty = availableProducts
      .map(product => ({
        ...product,
        warrantyText: formatWarranty(product.warranty_days)
      }))
      .filter(product => product.warrantyText);

    const uniqueWarrantyPeriods = [
      ...new Set(productsWithWarranty.map(product => product.warrantyText))
    ];

    if (
      productsWithWarranty.length > 0 &&
      uniqueWarrantyPeriods.length === 1 &&
      productsWithWarranty.length === availableProducts.length
    ) {
      reply =
        `Nossos carregadores possuem ${uniqueWarrantyPeriods[0]} de garantia contra defeito de fabricação. ` +
        `A garantia não cobre danos por mau uso, queda, umidade ou alterações no produto.`;
    } else if (productsWithWarranty.length > 0) {
      reply =
        `O prazo de garantia varia conforme o modelo. Você quer saber do Carregador Turbo 67W ou do 120W?`;
    } else {
      reply =
        `Você quer saber a garantia do Carregador Turbo 67W ou do 120W? ` +
        `Me diga qual modelo para eu confirmar o prazo correto.`;
    }
  }

  state.last_bot_message = reply;

  return [{
    json: {
      ...b,
      state,
      reply,
      detectedQuantity,
      createOrder: false,
      technicalQuestion: 'warranty',
      preserveCurrentReply: true
    }
  }];
}

// Pergunta técnica sobre tensão/bivolt.
// Nunca trata "é bivolt?" como nome de produto.
if (asksVoltageInput) {
  const previousProduct =
    old.product_id
      ? products.find(p => String(p.product_id) === String(old.product_id))
      : null;

  const targetProduct = selected || previousProduct || null;

  if (!targetProduct) {
    reply =
      'Me diga qual carregador você quer consultar para eu confirmar a tensão cadastrada desse produto.';
  } else {
    reply =
      `Sim, o ${targetProduct.product_name} é bivolt e pode ser usado normalmente ` +
      `em redes 110V e 220V.`;
  }

  state.last_bot_message = reply;

  return [{
    json: {
      ...b,
      state,
      reply,
      detectedQuantity,
      createOrder: false,
      technicalQuestion: 'input_voltage',
      preserveCurrentReply: true
    }
  }];
}

// Acompanhamento de produto fora do catálogo.
// Mantém a conversa humana e registra o interesse, sem repetir a lista de carregadores.
if (asksRestockForecast && hasPreviousUnknownContext) {
  const requestedProduct = detectRequestedExternalProduct(previousUnknownQuestion);

  reply =
    `Ainda não temos uma previsão confirmada para ${requestedProduct}, ` +
    `mas já registramos seu interesse. Estamos avaliando os produtos mais pedidos ` +
    `para trazer ao estoque. Assim que estiver disponível, podemos avisar você por aqui.`;

  state.learned_terms = uniqueTerms([
    ...(Array.isArray(state.learned_terms) ? state.learned_terms : []),
    requestedProduct,
    'interesse de estoque'
  ]);

  externalInterest = {
    requested_product: requestedProduct,
    context_type: 'restock_forecast',
    request_text: currentOriginal,
    previous_request_text: previousUnknownQuestion,
    customer_terms: uniqueTerms([
      requestedProduct,
      ...(Array.isArray(ai.customer_terms) ? ai.customer_terms : [])
    ])
  };
}

// Pergunta sobre cabo Tipo-C sem produto definido.
// Em vez de tratar como produto inexistente, pede apenas a potência desejada.
else if (!selected && asksTypeCCable) {
  const typeCProducts = availableProducts.filter(product =>
    normalize(product.connector_type).includes('tipo c') ||
    normalize(product.connector_type).includes('type c') ||
    normalize(product.connector_type).includes('usb c') ||
    normalize(product.description).includes('tipo c') ||
    normalize(product.description).includes('usb c')
  );

  if (typeCProducts.length === 1) {
    reply =
      `Sim, temos opção com conexão Tipo-C: ${typeCProducts[0].product_name}. ` +
      `Você quer saber o preço ou fazer um pedido?`;
  } else if (typeCProducts.length > 1) {
    reply =
      `Temos carregadores com conexão Tipo-C. Você está procurando o modelo ` +
      `${typeCProducts.map(p => p.power_watts ? `${p.power_watts}W` : p.product_name).join(' ou ')}?`;
  } else {
    reply =
      'Você está perguntando sobre o cabo ou sobre a fonte? Me diga qual aparelho você usa para eu mostrar somente as opções corretas.';
  }
}

// Produto realmente solicitado fora do catálogo.
// Só informa indisponibilidade quando há produto identificável + intenção explícita de compra/consulta de estoque.
// Dúvida técnica, compatibilidade, conversa comum ou frase desconhecida nunca cai nesta resposta.
else if (
  !selected &&
  !ambiguousProducts.length &&
  explicitExternalProductRequest
) {
  const requestedProduct = explicitExternalProduct;

  reply =
    `No momento não trabalhamos com ${requestedProduct} em estoque. ` +
    `Posso registrar seu interesse e avisar quando tivermos novidade. ` +
    `Você procura algum modelo ou faixa de preço específica?`;

  state.learned_terms = uniqueTerms([
    ...(Array.isArray(state.learned_terms) ? state.learned_terms : []),
    requestedProduct,
    'produto solicitado fora do catálogo'
  ]);

  externalInterest = {
    requested_product: requestedProduct,
    context_type: 'new_product_request',
    request_text: currentOriginal,
    previous_request_text: null,
    customer_terms: uniqueTerms([
      requestedProduct,
      ...(Array.isArray(ai.customer_terms) ? ai.customer_terms : [])
    ])
  };
}

// Fallback conversacional seguro.
// Se a mensagem não for um pedido comercial explícito de produto fora do catálogo,
// preserva a resposta inteligente da IA e nunca inventa indisponibilidade de estoque.
else if (
  !selected &&
  !ambiguousProducts.length &&
  !explicitExternalProductRequest &&
  ['product_question', 'technical_question', 'compatibility_question', 'small_talk', 'other', 'human_support'].includes(ai.intent)
) {
  reply = String(ai.reply ?? '').trim();

  if (!reply) {
    reply =
      'Entendi. Pode me explicar um pouco melhor o que você quer saber? ' +
      'Assim eu consigo orientar corretamente.';
  }

  // Proteção final contra o padrão incorreto antigo.
  if (
    /\bno momento nao temos\b|\bnao temos .* disponivel no estoque\b/i.test(
      normalize(reply)
    )
  ) {
    reply =
      'Entendi sua dúvida. Pode me dizer se você quer saber sobre compatibilidade, ' +
      'entrada do carregador, potência, garantia ou outro detalhe técnico?';
  }
}

// Produto ambíguo: pedir escolha.
if (ambiguousProducts.length) {
  reply =
    `Encontrei mais de uma opção:\n` +
    ambiguousProducts
      .map(p => `• ${p.product_name} — R$ ${money(p.sale_price)}`)
      .join('\n') +
    `\n\nQual delas você deseja?`;
}

// Produto selecionado agora.
if (
  shouldAdvanceCheckout &&
  selected &&
  String(selected.product_id) !== String(old.product_id ?? '') &&
  !quantity
) {
  reply =
    `Perfeito! ${selected.product_name}, por R$ ${money(selected.sale_price)}. ` +
    `Quantas unidades você deseja?`;
}

if (shouldAdvanceCheckout && correctedQuantity !== null && state.product_name) {
  reply =
    missing[0] === 'nome'
      ? `Certo, corrigi para ${quantity} unidade${quantity > 1 ? 's' : ''}. Qual é o nome de quem vai receber?`
      : missing[0] === 'bairro'
        ? `Certo, corrigi para ${quantity} unidade${quantity > 1 ? 's' : ''}. Qual é o bairro da entrega?`
        : reply;
}

// Só pergunta a próxima informação faltante. Não repete produto/preço sem necessidade.
if (shouldAdvanceCheckout && state.product_id && state.quantity) {
  if (missing[0] === 'nome') {
    reply = 'Qual é o nome de quem vai receber?';
  } else if (missing[0] === 'bairro') {
    reply = 'Qual é o bairro ou conjunto da entrega?';
  } else if (missing[0] === 'endereço') {
    // A taxa será aplicada pelo próximo nó.
    reply = 'Agora envie o endereço completo da entrega.';
  } else if (missing[0] === 'pagamento') {
    reply = 'O pagamento será por Pix ou dinheiro na entrega?';
  }
}

if (shouldAdvanceCheckout && !ai.cancel_order && missing.length === 0 && !ai.confirm_order) {
  const productsTotal = Number(state.unit_price) * Number(state.quantity);
  const deliveryFee = Number(state.delivery_fee ?? 0);
  const total = productsTotal + deliveryFee;

  reply =
    `Confira seu pedido:\n\n` +
    `• ${state.product_name}\n` +
    `• Quantidade: ${state.quantity}\n` +
    `• Produtos: R$ ${money(productsTotal)}\n` +
    `• Bairro: ${state.neighborhood}\n` +
    `• Taxa de entrega: ${deliveryFee === 0 ? 'Grátis' : `R$ ${money(deliveryFee)}`}\n` +
    `• Endereço: ${state.address}` +
    `${state.reference ? `\n• Referência: ${state.reference}` : ''}\n` +
    `• Pagamento: ${state.payment_method === 'cash' ? 'dinheiro na entrega' : 'Pix'}\n` +
    `• Total: R$ ${money(total)}\n\n` +
    `Responda CONFIRMAR para finalizar.`;
}

if (ai.confirm_order && missing.length) {
  reply = `Antes de finalizar, preciso confirmar: ${missing[0]}.`;
}

// PROTEÇÃO v23.9.1: nenhuma rota pode chegar ao envio com reply vazio.
// Gera uma próxima ação contextual quando a rota rápida apenas atualizou a sessão.
if (!String(reply ?? '').trim()) {
  const nextMissing = missing[0] ?? null;

  if (state.product_id && !state.quantity) {
    reply =
      `Perfeito! ${state.product_name}, por R$ ${money(state.unit_price)}. ` +
      `Quantas unidades você deseja?`;
  } else if (state.product_id && state.quantity && nextMissing === 'nome') {
    reply = 'Qual é o nome de quem vai receber?';
  } else if (state.product_id && state.quantity && nextMissing === 'bairro') {
    reply = 'Qual é o bairro ou conjunto da entrega?';
  } else if (state.product_id && state.quantity && nextMissing === 'endereço') {
    reply = 'Agora envie o endereço completo da entrega.';
  } else if (state.product_id && state.quantity && nextMissing === 'pagamento') {
    reply = 'O pagamento será por Pix ou dinheiro na entrega?';
  } else if (state.neighborhood && nextMissing === 'taxa de entrega') {
    reply = 'Estou calculando a taxa de entrega para esse bairro.';
  } else if (ai.confirm_order && missing.length === 0) {
    reply = 'Pedido confirmado. Estou finalizando o registro.';
  } else {
    reply = 'Recebi sua mensagem. Pode me dizer como posso ajudar?';
  }
}

// Evita repetição literal da última mensagem.
if (
  reply &&
  old.last_bot_message &&
  normalize(reply) === normalize(old.last_bot_message)
) {
  const next =
    missing[0] === 'quantidade' ? 'Quantas unidades você deseja?' :
    missing[0] === 'nome' ? 'Qual é o nome de quem vai receber?' :
    missing[0] === 'bairro' ? 'Qual é o bairro ou conjunto da entrega?' :
    missing[0] === 'endereço' ? 'Envie o endereço completo da entrega.' :
    missing[0] === 'pagamento' ? 'O pagamento será por Pix ou dinheiro?' :
    null;

  if (next && normalize(next) !== normalize(old.last_bot_message)) {
    reply = next;
  }
}

state.last_bot_message = reply;

return [{
  json: {
    ...b,
    state,
    reply,
    detectedQuantity,
    preserveCurrentReply: isContextualInterrupt,
    answersPendingField,
    pendingFieldBefore: pendingBefore,
    messageRole,
    shouldAdvanceCheckout,

    registerExternalInterest: Boolean(externalInterest),
    externalInterest: externalInterest
      ? {
          ...externalInterest,
          customer_number: b.number,
          customer_name:
            state.customer_name ||
            (b.customerName && b.customerName !== 'Cliente'
              ? b.customerName
              : null),
          source_message_id: b.messageId || `${b.number}-${Date.now()}`,
          detected_at: new Date().toISOString()
        }
      : null,

    createOrder:
      !ai.cancel_order &&
      ai.confirm_order &&
      missing.length === 0
  }
}];

const r = $input.first().json;
const d = r.data ?? {};
const b = $('Aplicar Estado Oficial Pós-Salvamento').first().json;

const reply =
  `Pedido confirmado com sucesso! ✅\n\n` +
  `Número: ${d.order_number ?? 'gerado'}\n` +
  `Total: R$ ${Number(d.total ?? 0).toFixed(2).replace('.', ',')}\n` +
  `Status: reservado\n\n` +
  `A equipe vai conferir no painel e seguir com a entrega.`;

return [{
  json: {
    ...b,
    reply,
    state: {
      ...b.state,
      status: 'reserved',
      checkout_phase: 'reserved',
      transaction_version: b.state?.transaction_version ?? 'v26',
      order_id: d.order_id ?? null,
      order_number: d.order_number ?? null,
      last_bot_message: reply,
      updated_at: new Date().toISOString()
    }
  }
}];

const source = $input.first().json;
let reply = String(source?.reply ?? '').trim();

// V1.3 — proteção final contra saudação com nome vazio.
// Mesmo que alguma rota/LLM produza "Oi, !", isso nunca chega ao WhatsApp.
reply = reply
  .replace(/\bOi\s*,\s*!/gi, 'Oi!')
  .replace(/\bOlá\s*,\s*!/gi, 'Olá!')
  .replace(/\bOla\s*,\s*!/gi, 'Olá!')
  .replace(/\bOi\s*,\s*(?=[.?!])/gi, 'Oi')
  .replace(/\bOlá\s*,\s*(?=[.?!])/gi, 'Olá');

if (!reply) {
  throw new Error('RESPOSTA_VAZIA_BLOQUEADA_ANTES_DO_WHATSAPP');
}

return [{ json: { ...source, reply } }];

