parameters.jsCode:
const consolidated = $('Consolidar Sessão').first().json;
const base = $('⚙️ Workflow Controller V').first().json ?? consolidated;
const rawItems = $input.all();

// v23.9.9: uma pergunta durante o checkout nunca pode ser substituída
// novamente pela mensagem da taxa/endereço.
if (base.preserveCurrentReply === true || base.checkoutPausedForQuestion === true) {
  const state = {
    ...(base.state ?? {}),
    last_bot_message: String(base.reply ?? '').trim(),
    updated_at: new Date().toISOString()
  };

  return [{
    json: {
      ...base,
      state,
      createOrder: false
    }
  }];
}

const rows = rawItems.flatMap(item => {
  const raw = item?.json;

  if (Array.isArray(raw)) {
    return raw;
  }

  if (Array.isArray(raw?.data)) {
    return raw.data;
  }

  if (
    raw &&
    typeof raw === "object" &&
    Object.keys(raw).length > 0
  ) {
    return [raw];
  }

  return [];
});

const state = {...base.state};
let reply = String(base.reply ?? '').trim();

// V25.6.4 — somente uma mensagem de bairro pode anunciar falha ou taxa.
// Produto, FAQ e outras intenções preservam a própria resposta.
const deliveryResolutionRoutes = new Set([
  "bairro_para_consulta_entrega",
  "bairro_extraido_de_frase",
  "bairro_entrega"
]);

const shouldAnnounceDeliveryResolution =
  deliveryResolutionRoutes.has(
    String(base.fast_route_reason ?? "")
  );


const money = value =>
  Number(value ?? 0).toFixed(2).replace('.', ',');

const normalize = value => String(value ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const cleanDeliveryText = value =>
  normalize(value)
    .replace(/^(?:eu moro|moro|fica|entrega|entregar|bairro|conjunto)\s+(?:na|no|em|para|pra)?\s*/, '')
    .replace(/^(?:na|no|em|para|pra|pro)\s+/, '')
    .replace(/\s+(?:para|pra|por favor)$/, '')
    .trim();

const stopWords = new Set([
  'a', 'o', 'as', 'os', 'da', 'do', 'das', 'dos',
  'de', 'em', 'no', 'na', 'para', 'pra', 'bairro',
  'conjunto', 'cidade'
]);

const tokens = value =>
  cleanDeliveryText(value)
    .split(' ')
    .filter(token =>
      token &&
      !stopWords.has(token)
    );

const requestedNeighborhood =
  cleanDeliveryText(state.neighborhood);

const requestedTokens =
  tokens(requestedNeighborhood);

const rankedZones = rows
  .map(row => {
    const zoneName = cleanDeliveryText(
      row.normalized_neighborhood ??
      row.neighborhood
    );

    const city = cleanDeliveryText(
      row.city ?? ''
    );

    const zoneTokens = tokens(zoneName);
    const combinedTokens = new Set([
      ...zoneTokens,
      ...tokens(city)
    ]);

    let score = 0;

    if (
      requestedNeighborhood &&
      requestedNeighborhood === zoneName
    ) {
      score = 1000;
    } else if (
      requestedNeighborhood &&
      cleanDeliveryText(
        `${row.neighborhood} ${row.city ?? ''}`
      ) === requestedNeighborhood
    ) {
      score = 980;
    } else if (
      zoneName.length >= 4 &&
      requestedNeighborhood.includes(zoneName)
    ) {
      score = 900 + zoneName.length;
    } else if (
      requestedNeighborhood.length >= 4 &&
      zoneName.includes(requestedNeighborhood)
    ) {
      score = 760 + requestedNeighborhood.length;
    } else if (
      zoneTokens.length > 0 &&
      zoneTokens.every(token =>
        requestedTokens.includes(token)
      )
    ) {
      score = 850 + zoneTokens.length * 10;
    } else if (
      requestedTokens.length > 0 &&
      requestedTokens.every(token =>
        combinedTokens.has(token)
      )
    ) {
      score = 800 + requestedTokens.length * 10;
    }

    if (
      city &&
      requestedNeighborhood.includes(city)
    ) {
      score += 80;
    }

    return {
      row,
      score,
      zoneName,
      city
    };
  })
  .filter(item => item.score > 0)
  .sort((a, b) =>
    b.score - a.score
  );

const top = rankedZones[0] ?? null;
const second = rankedZones[1] ?? null;

const resolutionAmbiguous =
  Boolean(
    top &&
    second &&
    top.score === second.score &&
    String(top.row.id) !== String(second.row.id)
  );

const found =
  top &&
  top.score >= 700 &&
  !resolutionAmbiguous
    ? {
        ...top.row,
        normalized_name:
          top.row.normalized_neighborhood
      }
    : null;

const ambiguousCandidates =
  resolutionAmbiguous
    ? rankedZones
        .filter(item =>
          item.score === top.score
        )
        .slice(0, 4)
        .map(item => item.row)
    : [];

const suspiciousNeighborhood = (() => {
  const value = normalize(state.neighborhood);
  if (!value) return false;
  if (/\b(?:67|120)\s*w\b/.test(value)) return true;
  return /\b(?:quero|vou querer|nao quero|nao vou querer|comprar|carregador|produto|trocar|mudar|cancelar|garantia|serve|funciona|comparar)\b/.test(value);
})();

// Última barreira contra repetição: produto nunca segue para consulta de bairro.
if (suspiciousNeighborhood) {
  const watts = normalize(state.neighborhood).match(/\b(67|120)\s*w\b/)?.[1] ?? null;
  const availableProduct = watts
    ? (Array.isArray(base.products) ? base.products : []).find(p =>
        Number(p.power_watts ?? 0) === Number(watts) ||
        normalize(p.product_name).includes(`${watts}w`)
      )
    : null;

  state.neighborhood = null;
  state.delivery_fee = null;

  if (!reply) {
    reply = availableProduct
      ? `Entendi. Você está falando do ${availableProduct.product_name}, não do bairro. Vou ajustar o produto primeiro.`
      : watts
        ? `Entendi. Você está falando do carregador ${watts}W, não do bairro. No momento ele não aparece disponível no estoque.`
        : 'Entendi. Essa mensagem é sobre o produto, não sobre o bairro.';
  }

  state.last_bot_message = reply;
  state.updated_at = new Date().toISOString();

  return [{
    json: {
      ...base,
      state,
      reply,
      createOrder: false,
      invalidNeighborhoodBlocked: true
    }
  }];
}

if (found && found.delivery_fee !== undefined && found.delivery_fee !== null) {
  state.neighborhood =
    found.neighborhood ??
    state.neighborhood;
  state.delivery_fee = Number(found.delivery_fee);

  const orderDataComplete = Boolean(
    state.product_id &&
    Number(state.quantity ?? 0) > 0 &&
    state.customer_name &&
    state.neighborhood &&
    state.address &&
    state.payment_method
  );

  // Se a rota rápida acabou de informar o pagamento, a taxa só ficou disponível aqui.
  // Nesse caso, monta o resumo agora, em vez de deixar reply vazio.
  if (orderDataComplete && !base.createOrder) {
    const productsTotal = Number(state.unit_price ?? 0) * Number(state.quantity ?? 0);
    const deliveryFee = Number(state.delivery_fee ?? 0);
    const total = productsTotal + deliveryFee;

    reply =
      `Confira seu pedido:\n\n` +
      `• ${state.product_name}\n` +
      `• Quantidade: ${state.quantity}\n` +
      `• Produtos: R$ ${money(productsTotal)}\n` +
      `• Bairro: ${state.neighborhood}\n` +
      `• Taxa de entrega: ${deliveryFee === 0 ? 'Grátis' : `R$ ${money(deliveryFee)}`}\n` +
      `• Endereço: ${state.address}` +
      `${state.reference ? `\n• Referência: ${state.reference}` : ''}\n` +
      `• Pagamento: ${state.payment_method === 'cash' ? 'dinheiro na entrega' : 'Pix'}\n` +
      `• Total: R$ ${money(total)}\n\n` +
      `Responda CONFIRMAR para finalizar.`;
  } else if (
    !state.address &&
    !base.preserveCurrentReply &&
    shouldAnnounceDeliveryResolution
  ) {
    reply = state.delivery_fee === 0
      ? `Entregamos em ${state.neighborhood} com entrega grátis. Agora envie o endereço completo da entrega.`
      : `Entregamos em ${state.neighborhood}. A taxa é R$ ${money(state.delivery_fee)}. Agora envie o endereço completo da entrega.`;
  }
} else {
  state.delivery_fee = null;

  if (
    !base.preserveCurrentReply &&
    shouldAnnounceDeliveryResolution
  ) {
    if (resolutionAmbiguous) {
      const options = ambiguousCandidates
        .map(row =>
          [row.neighborhood, row.city]
            .filter(Boolean)
            .join(' — ')
        )
        .join('; ');

      state.neighborhood = null;

      reply =
        `Encontrei mais de uma região parecida: ${options}. ` +
        `Qual delas é a sua?`;
    } else {
      state.neighborhood = null;

      reply =
        'Não consegui identificar o bairro com segurança. ' +
        'Envie somente o nome do bairro ou conjunto e a cidade.';
    }
  }
}

if (!reply) {
  reply = 'Recebi sua mensagem, mas ainda preciso confirmar os dados da entrega.';
}

state.last_bot_message = reply;
state.updated_at = new Date().toISOString();

return [{
  json: {
    ...base,
    state,
    reply,
    createOrder:
      Boolean(base.createOrder) &&
      state.delivery_fee !== null &&
      state.delivery_fee !== undefined
  }
}];

const base =
  $('Aplicar Taxa do Supabase').isExecuted
    ? $('Aplicar Taxa do Supabase').first().json
    : $('Manter Inteligência da v16').first().json;

const raw = $input.first().json;

const rows =
  Array.isArray(raw) ? raw :
  Array.isArray(raw?.data) ? raw.data :
  raw && Object.keys(raw).length ? [raw] :
  [];

const tier = rows[0] ?? null;
const state = {...base.state};

const quantity = Number(state.quantity ?? 0);
const unitPrice = Number(state.unit_price ?? 0);

const productsTotal =
  tier && tier.fixed_total_price !== undefined && tier.fixed_total_price !== null
    ? Number(tier.fixed_total_price)
    : unitPrice * quantity;

state.products_total = productsTotal;
state.price_source = tier ? 'product_price_tiers' : 'sale_price';

let reply = base.reply;

const complete =
  Boolean(state.product_id) &&
  quantity >= 1 &&
  Boolean(state.neighborhood) &&
  Boolean(state.address) &&
  Boolean(state.payment_method) &&
  state.delivery_fee !== null &&
  state.delivery_fee !== undefined;

if (complete && !base.createOrder && !base.preserveCurrentReply) {
  const deliveryFee = Number(state.delivery_fee ?? 0);
  const total = productsTotal + deliveryFee;

  reply =
    `Confira seu pedido:\n\n` +
    `• ${state.product_name}\n` +
    `• Quantidade: ${quantity}\n` +
    `• Produtos: R$ ${productsTotal.toFixed(2).replace('.', ',')}\n` +
    `• Bairro: ${state.neighborhood}\n` +
    `• Taxa de entrega: ${deliveryFee === 0 ? 'Grátis' : `R$ ${deliveryFee.toFixed(2).replace('.', ',')}`}\n` +
    `• Endereço: ${state.address}` +
    `${state.reference ? `\n• Referência: ${state.reference}` : ''}\n` +
    `• Pagamento: ${state.payment_method === 'cash' ? 'dinheiro na entrega' : 'Pix'}\n` +
    `• Total: R$ ${total.toFixed(2).replace('.', ',')}\n\n` +
    `Responda CONFIRMAR para finalizar.`;
}

state.last_bot_message = reply;
state.updated_at = new Date().toISOString();

return [{
  json: {
    ...base,
    state,
    reply
  }
}];

const base =
  $('Aplicar Taxa do Supabase').isExecuted
    ? $('Aplicar Taxa do Supabase').first().json
    : $('Manter Inteligência da v16').first().json;

const state = {...base.state};
const quantity = Number(state.quantity ?? 0);
const unitPrice = Number(state.unit_price ?? 0);

state.products_total = unitPrice * quantity;
state.price_source = 'sale_price';
state.updated_at = new Date().toISOString();

return [{
  json: {
    ...base,
    state
  }
}];

