const __siteText = String($json.text ?? '').trim();
const __siteOrderMatch = __siteText.match(/Fiz meu pedido pelo site\.\s*Pedido\s+([A-Z0-9-]+)/i);

return [{
  json: {
    ...$json,
    isSiteOrder: Boolean(__siteOrderMatch),
    siteOrderNumber: __siteOrderMatch?.[1] ?? null,
    evolutionBaseUrl: 'https://evolution.vectradev.shop',
    evolutionInstance: 'miranda-express',
    supabaseUrl: 'https://qudpndluldjudukelwxd.supabase.co',
    openaiModel: 'gpt-5-mini',
    visionModel: 'gpt-5-mini',
    storeName: 'Miranda Express',
    storefrontUrl: 'https://loja.vectradev.shop',
    storeAddressText: 'Travessa 10, nº 31 – Conjunto Catalina – Bairro Mangueirão – Belém/PA',
    storeWhatsappDisplay: '(91) 92007-8425',
    commerceApiUrl: 'https://api.vectradev.shop',
    companyId: 'e2e1f5bc-3f6c-4868-9d9c-5c8226df9b3d',
    storeId: 'f4a134bb-00fc-4314-bcd5-9d5cd45f036d'
  }
}];

// Libera somente o primeiro processamento de cada message_id.
//
// O HTTP Request do Supabase pode chegar ao n8n como JSON normal OU como
// um stream compactado serializado (_readableState.buffer). Este node
// decodifica os dois formatos.
//
// - inserção nova: o Supabase devolve a linha com message_id;
// - duplicata: o Supabase devolve [] e este node retorna zero itens.

const original = $('Configuração Geral1').first().json;
const expectedId = String(original.messageId ?? '').trim();
const rawInputs = $input.all().map(item => item.json);

function decodeStreamResponse(value) {
  if (!value || typeof value !== 'object') return value;

  const buffers =
    value?._readableState?.buffer ??
    value?.body?._readableState?.buffer ??
    value?.data?._readableState?.buffer ??
    null;

  if (!Array.isArray(buffers) || buffers.length === 0) {
    return value;
  }

  const bytes = [];

  for (const part of buffers) {
    const data =
      part?.data ??
      part?.chunk?.data ??
      part?.buffer?.data ??
      null;

    if (Array.isArray(data)) {
      bytes.push(...data);
    }
  }

  if (bytes.length === 0) {
    return value;
  }

  const text = Buffer.from(bytes).toString('utf8').trim();

  if (!text) return [];

  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

function collectRows(value, rows = [], depth = 0) {
  if (depth > 12 || value === null || value === undefined) return rows;

  const decoded = decodeStreamResponse(value);

  if (decoded !== value) {
    return collectRows(decoded, rows, depth + 1);
  }

  if (typeof value === 'string') {
    const text = value.trim();

    if (
      (text.startsWith('{') && text.endsWith('}')) ||
      (text.startsWith('[') && text.endsWith(']'))
    ) {
      try {
        collectRows(JSON.parse(text), rows, depth + 1);
      } catch {}
    }

    return rows;
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      collectRows(item, rows, depth + 1);
    }

    return rows;
  }

  if (typeof value !== 'object') return rows;

  if (Object.prototype.hasOwnProperty.call(value, 'message_id')) {
    rows.push(value);
  }

  // Depois de tentar decodificar o stream, percorre somente estruturas
  // comuns de resposta. Isso evita vasculhar propriedades internas do socket.
  for (const key of ['body', 'data', 'result', 'results', 'rows', 'response']) {
    if (value[key] !== undefined) {
      collectRows(value[key], rows, depth + 1);
    }
  }

  return rows;
}

const rows = collectRows(rawInputs);

const inserted = rows.find(row =>
  String(row.message_id ?? '').trim() === expectedId
);

// Se não existe linha inserida, o message_id já havia sido registrado.
// Zero itens encerra o ramo antes da IA e antes do envio ao WhatsApp.
if (!inserted) {
  return [];
}

return [{
  json: {
    ...original,
    event_is_new: true,
    event_lock_message_id: expectedId,
    event_lock_received_at: inserted.received_at ?? null
  }
}];

const messages = $('Normalizar Mensagens').all().map(item => item.json ?? {});
const batches = $('Deduplicar e Agrupar em Lotes de 25').all().map(item => item.json ?? {});
const candidates = $('Gerar Candidatos de Conhecimento').all()
  .map(item => item.json ?? {})
  .filter(item => item.category);

const customerMessages = messages.filter(item => !item.from_me);
const botMessages = messages.filter(item => Boolean(item.from_me));
