const cleanNeighborhood = value => {
  let raw = String(value ?? '').trim();
  if (!raw) return null;

  raw = raw
    .replace(/[?!.,;:]+$/g, '')
    .replace(/^\s*(?:bairro\s+)?(?:da|do|de)\s+/i, '')
    .replace(/^\s*bairro\s+/i, '')
    .replace(/^\s*(?:na|no|em|pra|para|pro)\s+/i, '')
    .replace(/\s+(?:para|pra|por favor)\s*$/i, '')
    .trim();

  if (!raw || raw.length < 2 || raw.length > 60) return null;
  if (/\d{2,3}\s*w/i.test(raw)) return null;
  if (/\b(?:carregador|garantia|pix|dinheiro|comprar|produto|celular)\b/i.test(raw)) return null;
  return raw;
};

const extractNeighborhoodFromDelivery = value => {
  const raw = String(value ?? '').trim();
  if (!raw) return null;

  const patterns = [
    /\bbairro\s+(?:da|do|de)?\s*([A-Za-zÀ-ÿ0-9][A-Za-zÀ-ÿ0-9 .'ºª-]{1,50})[?!.,;:]*$/i,
    /\b(?:na|no|em)\s+([A-Za-zÀ-ÿ0-9][A-Za-zÀ-ÿ0-9 .'ºª-]{1,50})[?!.,;:]*$/i,
    /\b(?:pra|para|pro)\s+(?:o|a)?\s*([A-Za-zÀ-ÿ0-9][A-Za-zÀ-ÿ0-9 .'ºª-]{1,50})[?!.,;:]*$/i
  ];

  for (const pattern of patterns) {
    const match = raw.match(pattern);
    const candidate = cleanNeighborhood(match?.[1]);
    if (candidate) return candidate;
  }

  // Resposta curta: "Cremação", "Bairro da Cremação", "Conjunto Catalina".
  if (/^[A-Za-zÀ-ÿ0-9][A-Za-zÀ-ÿ0-9 .'ºª-]{1,59}$/.test(raw)) {
    return cleanNeighborhood(raw);
  }

  return null;
};
