const useAi = reason => {
  // ====================================================
  // V25.7 — PAYLOAD ENXUTO PARA OPENAI
  // 1) limpa histórico gigante
  // 2) filtra compatibilityCatalog por aparelho/contexto atual
  // 3) remove campos de debug pesados
  // ====================================================

  const safeSession = {
    ...(b.session ?? {})
  };

  const lastBot = String(safeSession.last_bot_message ?? '').trim();

  if (lastBot.length > 900) {
    safeSession.last_bot_message =
      'Resposta anterior extensa omitida para controle de contexto.';
  }

  const lastCustomer = String(safeSession.last_customer_message ?? '').trim();

  if (lastCustomer.length > 1800) {
    safeSession.last_customer_message =
      lastCustomer.slice(-1800);
  }

  const sourceCatalog = Array.isArray(b.compatibilityCatalog)
    ? b.compatibilityCatalog
    : [];

  const searchContext = normalize([
    text,
    b.quotedText,
    b.quoted_text,
    safeSession.device_brand,
    safeSession.device_model,
    safeSession.product_name
  ].filter(Boolean).join(' '));

  const scoredCatalog = sourceCatalog
    .map(item => {
      const brand = normalize(item?.brand);
      const model = normalize(item?.model);

      const aliases = Array.isArray(item?.aliases)
        ? item.aliases.map(normalize).filter(Boolean)
        : [];

      let score = 0;

      if (brand && searchContext.includes(brand)) {
        score += 25;
      }

      if (model && searchContext.includes(model)) {
        score += 100;
      }

      for (const alias of aliases) {
        if (alias && searchContext.includes(alias)) {
          score = Math.max(score, 110);
        }
      }

      const modelTokens = model
        .split(' ')
        .filter(token => token.length >= 2);

      const hits = modelTokens
        .filter(token => searchContext.includes(token))
        .length;

      score = Math.max(score, hits * 20);

      if (
        safeSession.product_id &&
        String(item?.product_id ?? '') === String(safeSession.product_id)
      ) {
        score += 15;
      }

      return { item, score };
    })
    .filter(x => x.score >= 40)
    .sort((a, b) => b.score - a.score);

  let safeCompatibilityCatalog = scoredCatalog
    .slice(0, 8)
    .map(x => x.item);

  // Se nenhum aparelho foi reconhecido, nunca envia a base inteira.
  // Quando houver produto em sessão, envia no máximo 4 registros ligados a ele.
  if (!safeCompatibilityCatalog.length && safeSession.product_id) {
    safeCompatibilityCatalog = sourceCatalog
      .filter(
        item =>
          String(item?.product_id ?? '') ===
          String(safeSession.product_id)
      )
      .slice(0, 4);
  }

  if (!safeCompatibilityCatalog.length) {
    safeCompatibilityCatalog = [];
  }

  const {
    catalog_debug,
    compatibility_debug,
    compatibilityCatalog: _fullCompatibilityCatalog,
    ...safeBase
  } = b;

  return [{
    json: {
      ...safeBase,
      session: safeSession,
      compatibilityCatalog: safeCompatibilityCatalog,

      use_openai: true,
      fast_route: false,
      fast_route_reason: reason,
      fast_ai: null,

      contextSanitized: true,
      compatibilityCatalogOriginalCount: sourceCatalog.length,
      compatibilityCatalogSentCount: safeCompatibilityCatalog.length
    }
  }];
};

