    powerOptions.length
  ) {
    reply =
      `${genericCatalogCategory.icon} Sim, temos carregadores disponíveis ` +
      `nas opções ${powerOptions.join(', ')}.\n\n` +
      `${productPreview}\n\n` +
      `Se você me disser a marca e o modelo do celular, eu indico a opção correta.`;
  } else {
    reply =
      `${genericCatalogCategory.icon} Sim, temos ` +
      `${genericCatalogCategory.plural} disponíveis:\n\n` +
      `${productPreview}`;
  }

  if (
    categoryProducts.length &&
    storefrontUrl
  ) {
    reply +=
      `\n\n🛍️ Catálogo completo:\n${storefrontUrl}`;
  }

  return fast(
    'disponibilidade_categoria_catalogo',
    {
      reply,
      intent: 'product_question',
      message_role: 'new_question',
      answers_pending_field: false,
      confirm_order: false,
      product_id: null,
      product_search_term: null,
