const earlyFaqPowerMatch = n.match(/\b(20|66|67|100|120)\s*w\b/);
const earlyFaqPower = earlyFaqPowerMatch
  ? Number(earlyFaqPowerMatch[1])
  : null;

const earlyPowerProduct = earlyFaqPower
  ? products.find(product =>
      Number(product.power_watts ?? 0) === earlyFaqPower ||
      normalize(product.product_name).includes(`${earlyFaqPower}w`)
    )
  : null;

// Ranqueia pelo termo explícito mais específico encontrado.
const earlyExplicitFaqRanking = products
  .map(product => {
    const matchedTerms = [
      product.product_name,
      ...(Array.isArray(product.aliases) ? product.aliases : [])
    ]
      .map(normalize)
      .filter(term => term.length >= 3 && n.includes(term))
      .sort((a, b) => b.length - a.length);

    return {
      product,
      matched_term: matchedTerms[0] ?? null,
      score: matchedTerms[0]?.length ?? 0
    };
  })
  .filter(item => item.score > 0)
  .sort((a, b) => b.score - a.score);

const earlyExplicitFaqProduct =
  earlyExplicitFaqRanking.length > 0 &&
  (
    earlyExplicitFaqRanking.length === 1 ||
    earlyExplicitFaqRanking[0].score >
      earlyExplicitFaqRanking[1].score
  )
    ? earlyExplicitFaqRanking[0].product
    : null;

const earlySessionFaqProduct = session.product_id
  ? products.find(product =>
      String(product.product_id) === String(session.product_id)
    )
  : null;

const earlyFaqProduct =
  earlyPowerProduct ??
  earlyExplicitFaqProduct ??
  earlySessionFaqProduct ??
  null;

const earlyMatchedProductFaqs =
  earlyFaqProduct && Array.isArray(earlyFaqProduct.faqs)
    ? earlyFaqProduct.faqs
        .filter(faq => {
          const terms = [
            ...(Array.isArray(faq.keywords)
              ? faq.keywords
              : []),
            ...(Array.isArray(faq.question_examples)
              ? faq.question_examples
              : [])
          ]
            .map(normalize)
            .filter(term => term.length >= 3);

          return terms.some(term => n.includes(term));
        })
        .sort(
          (a, b) =>
            Number(a.priority ?? 100) -
            Number(b.priority ?? 100)
        )
    : [];

if (earlyMatchedProductFaqs.length > 0) {
  const faq = earlyMatchedProductFaqs[0];

  return fast("faq_produto_prioritaria_sem_openai", {
    reply: faq.approved_answer,
    intent: "technical_question",
    message_role: "new_question",
    product_id: earlyFaqProduct.product_id ?? null,
    product_search_term:
      earlyFaqProduct.product_name ?? null,
    answers_pending_field: false,
    confirm_order: false
