  ? products.filter(
      p =>
        Number(p.power_watts ?? 0) === watts ||
        normalize(p.product_name).includes(`${watts}w`)
    )
  : [];
const mentionedProduct =
  mentionedProducts[0] ?? null;

// V25.6.3: FAQ aprovada do produto responde sem OpenAI.
const sessionFaqProduct = session.product_id
  ? products.find(p => String(p.product_id) === String(session.product_id))
  : null;
const explicitFaqProducts = products.filter(p => {
  const terms = [p.product_name, ...(Array.isArray(p.aliases) ? p.aliases : [])]
    .map(normalize)
    .filter(term => term.length >= 3);
  return terms.some(term => n.includes(term));
});
const faqProduct = mentionedProduct ?? sessionFaqProduct ??
  (explicitFaqProducts.length === 1 ? explicitFaqProducts[0] : null);
const matchedProductFaqs = faqProduct && Array.isArray(faqProduct.faqs)
  ? faqProduct.faqs
      .filter(faq => {
        const terms = [
          ...(Array.isArray(faq.keywords) ? faq.keywords : []),
          ...(Array.isArray(faq.question_examples) ? faq.question_examples : [])
        ].map(normalize).filter(term => term.length >= 3);
        return terms.some(term => n.includes(term));
      })
      .sort((a, b) => Number(a.priority ?? 100) - Number(b.priority ?? 100))
  : [];

if (matchedProductFaqs.length > 0) {
  const faq = matchedProductFaqs[0];
  return fast("faq_produto_aprovada_sem_openai", {
    reply: faq.approved_answer,
    intent: "technical_question",
    message_role: "new_question",
    product_id: faqProduct.product_id ?? null,
    product_search_term: faqProduct.product_name ?? null,
    answers_pending_field: false,
    confirm_order: false
  });
}

const productQuestionCue =
  /\b(quanto|preco|preço|valor|garantia|serve|funciona|compativel|compatível|carrega|qual|como|tem|têm|aplica|aplicacao|adequado|apropriado|diferenca|comparar)\b|\?/.test(n);
const productPurchaseCue =
  /\b(quero|vou querer|pode separar|separa|reservar|reserva|comprar|pode ser|fica com|manda|esse|essa|troca|trocar|muda|mudar)\b/.test(n);
const exactPowerOnlyChoice = /^(carregador )?\d{1,3}\s*w$/.test(n);

// Produto citado por potência, mas ausente do catálogo/estoque atual.
// Nunca deixa a frase cair como bairro ou endereço.
if (
  watts &&
  !mentionedProduct &&
  !productQuestionCue &&
  (productPurchaseCue || exactPowerOnlyChoice || pending === 'produto')
) {
  const alternatives = products
    .filter(p => Number(p.available_quantity ?? 0) > 0)
    .slice(0, 3);

  const alternativeText = alternatives.length
    ? ` Tenho disponível: ${alternatives.map(p => `${p.product_name} por R$ ${money(p.sale_price)}`).join('; ')}.`
    : '';

  return fast('produto_por_potencia_sem_estoque', {
    reply: `No momento, o carregador ${watts}W não está disponível no estoque.${alternativeText} Quer escolher uma dessas opções ou prefere aguardar?`,
    intent: 'product_question',
    message_role: 'new_question',
    answers_pending_field: false
  });
}

// V25.6.4: disponibilidade e estoque respondidos pelo catálogo da empresa.
// Perguntas simples como "tem carregador de 67W?" nunca usam OpenAI.
const availabilityQuestion =
  /\b(tem|vende|vendem|disponivel|estoque)\b/.test(n);

if (watts && availabilityQuestion) {
  const availableProducts = mentionedProducts
    .filter(
      product =>
        Number(
          product.available_quantity ?? 0
        ) > 0
    );

  if (availableProducts.length === 1) {
    const product = availableProducts[0];

    return fast(
      'disponibilidade_catalogo_sem_openai',
      {
        reply:
          `Sim, temos ${product.product_name} disponível por R$ ${money(product.sale_price)}. Quer que eu reserve uma unidade?`,
        intent: 'product_question',
        message_role: 'new_question',
        product_id:
          product.product_id ?? null,
        product_search_term:
          product.product_name ?? null,
        answers_pending_field: false,
        confirm_order: false
      }
    );
  }

  if (availableProducts.length > 1) {
    const options = availableProducts
      .slice(0, 5)
      .map(
        product =>
          `• ${product.product_name} — R$ ${money(product.sale_price)}`
      )
      .join('\n');

    return fast(
      'disponibilidade_catalogo_sem_openai',
      {
        reply:
          `Sim, temos estas opções de ${watts}W:\n${options}\n\nQual delas você deseja?`,
        intent: 'product_question',
        message_role: 'new_question',
        answers_pending_field: false,
        confirm_order: false
      }
    );
  }

  return fast(
    'disponibilidade_catalogo_sem_openai',
    {
      reply:
        `No momento, não encontrei carregador de ${watts}W disponível no catálogo. Quer ver outras potências disponíveis?`,
      intent: 'product_question',
      message_role: 'new_question',
      answers_pending_field: false,
      confirm_order: false
    }
  );
}

// V25.6.3: preço vem exclusivamente do catálogo carregado nesta execução.
if (mentionedProduct && /\b(?:quanto|preco|valor)\b/.test(n)) {
  const available = Number(mentionedProduct.available_quantity ?? 0);
  return fast("preco_oficial_catalogo", {
    reply: available > 0
      ? `${mentionedProduct.product_name} custa R$ ${money(mentionedProduct.sale_price)}.`
      : `${mentionedProduct.product_name} está sem estoque disponível no momento.`,
    intent: "product_question",
    message_role: "new_question",
    product_id: mentionedProduct.product_id ?? null,
    product_search_term: mentionedProduct.product_name,
    answers_pending_field: false,
    confirm_order: false
  });
}

// 3) Perguntas técnicas que o Consolidar Sessão já resolve pelo catálogo.
if (/\bgarantia\b|\btempo de garantia\b|\bquantos (dias|meses) de garantia\b|\btroca por defeito\b/i.test(n)) {
  return fast('garantia_catalogo', {
    intent: 'technical_question',
    message_role: 'new_question',
    product_id: session.product_id ?? null,
    product_search_term: mentionedProduct ? String(mentionedProduct.product_name) : null
  });
}

if (/\bbivolt\b|\bbi volt\b|\bvoltagem\b|\btensao de entrada\b|\bfunciona em 110\b|\bfunciona em 220\b|\b110 e 220\b|\b110 ou 220\b/i.test(n)) {
  return fast('bivolt_catalogo', {
    intent: 'technical_question',
    message_role: 'new_question',
