    product_search_term: mentionedProduct ? String(mentionedProduct.product_name) : null
  });
}

const previousBotRequestedDevice =
  /(?:marca e (?:o )?modelo|somente a marca e (?:o )?modelo|qual (?:e|é) a marca e (?:o )?modelo|qual o modelo do celular|me diga o modelo do celular|voce quis dizer|você quis dizer|confirma.*modelo|confirmar.*modelo)/.test(previousBot);

const currentDeviceText = n
  .replace(/^(?:e um|e uma|e|eh|meu celular e|meu aparelho e|o modelo e|modelo e)\s+/, '')
  .trim();

const reverseSamsungModel =
  /^(?:[asmxg]\s*\d{1,3}(?:\s*[45]g)?)\s+(?:samsung|sansung|galaxy)$/.test(currentDeviceText);
const modelOnlyDevice =
  /^(?:[asmxg]\s*\d{1,3}(?:\s*[45]g)?|g\s*\d{1,3}(?:\s*[45]g)?)$/.test(currentDeviceText);
const previousBotMentionsConcreteDevice =
  /\b(?:samsung|sansung|galaxy|xiaomi|redmi|poco|motorola|moto|iphone|apple|realme)\b.*\b(?:[asmxg]\s*\d{1,3}|g\s*\d{1,3}|note\s*\d+|iphone\s*\d+)\b/.test(previousBot);

const standaloneDeviceModel =
  /^(?:samsung|sansung|galaxy|xiaomi|redmi|poco|motorola|moto|iphone|apple|realme|oppo|infinix|tecno|asus|zenfone|lg|nokia)\s+[a-z0-9][a-z0-9 +._-]{0,40}$/.test(currentDeviceText) ||
  /^(?:samsung|sansung|galaxy)\s*[asmxg]\s*\d{1,3}(?:\s*[45]g)?$/.test(currentDeviceText) ||
  reverseSamsungModel ||
  (modelOnlyDevice && (previousBotRequestedDevice || previousBotMentionsConcreteDevice || Boolean(session.device_brand)));

// V25.6.2: "isso", "sim" ou o modelo curto depois de uma confirmação de aparelho
// continuam a compatibilidade; nunca viram encerramento social.
const contextualDeviceConfirmation =
  (previousBotRequestedDevice || previousBotMentionsConcreteDevice) &&
  (
    /^(?:s+i+m+|i+s+s+o+(?:\s+m+e+s+m+o+)?|e+s+s+e+(?:\s+m+e+s+m+o+)?|e+\s+e+s+s+e+|c+o+r+r+e+t+o+|e+x+a+t+o+|q+u+e+r+o+|p+o+d+e+\s+s+e+r+)$/.test(n) ||
