}

// Quando o robô pediu marca/modelo, a resposta nunca pode virar endereço ou pagamento.
if (standaloneDeviceModel && (previousBotRequestedDevice || previousBotMentionsConcreteDevice || Boolean(session.product_id) || Boolean(session.device_brand))) {
  return fast('modelo_celular_em_resposta', {
    intent: 'compatibility_question',
    message_role: 'new_question',
    answers_pending_field: false,
    product_id: session.product_id ?? null,
    customer_terms: [text]
  });
}

const compatibilityIntent =
  /\b(pra|para|pro|no|na|serve|funciona|compativel|carrega|carregar|usar|aplica|aplicase|aplicacao|adequado|apropriado)\b/.test(n) &&
  /\b(samsung|sansung|galaxy|xiaomi|redmi|poco|motorola|moto|iphone|apple|realme|oppo|infinix|tecno|asus|zenfone|lg|nokia|a\s*\d{1,3}|s\s*\d{1,3}|m\s*\d{1,3}|note\s*\d+|g\s*\d{1,3}|x\s*\d{1,3})\b/.test(n);

// V25.6.1 — aparelho já informado, mas ainda sem linha aprovada de compatibilidade.
// Esta regra precisa vir ANTES da rota genérica de compatibilidade; caso contrário,
// o bot volta a pedir marca/modelo mesmo já tendo entendido o aparelho.
const compatibilityMemory =
  b.compatibility && typeof b.compatibility === 'object'
    ? b.compatibility
    : {};

const knownBrand = String(
  compatibilityMemory.device_brand || session.device_brand || ''
).trim();
const knownModel = String(
  compatibilityMemory.device_model || session.device_model || ''
).trim();
const knownBrandNorm = normalize(knownBrand);
const knownModelNorm = normalize(knownModel);
const knownDeviceLabel =
  knownModelNorm && knownBrandNorm && knownModelNorm.startsWith(knownBrandNorm + ' ')
    ? knownModel
    : [knownBrand, knownModel].filter(Boolean).join(' ').trim();

if (
  compatibilityMemory.handled === true &&
  compatibilityMemory.found !== true &&
  Boolean(knownDeviceLabel)
) {
  return fast('aparelho_conhecido_sem_compatibilidade_aprovada', {
    reply: `Já identifiquei seu aparelho como ${knownDeviceLabel}. Esse modelo ainda não está na nossa base aprovada de compatibilidade, então não vou te indicar um carregador no chute. Preciso confirmar a opção correta para ele.`,
    intent: 'compatibility_question',
    message_role: 'new_question',
    answers_pending_field: false,
    product_id: session.product_id ?? null
  });
}

if (compatibilityIntent) {
  return fast('compatibilidade_catalogo', {
    intent: 'compatibility_question',
    message_role: 'new_question',
    product_id: session.product_id ?? null
  });
}

// 4) Escolha clara de um produto real do catálogo.
const questionCue = productQuestionCue;
const purchaseCue = productPurchaseCue;
const exactPowerOnly = exactPowerOnlyChoice;

if (mentionedProduct && !questionCue && (purchaseCue || exactPowerOnly || pending === 'produto')) {
  return fast('produto_por_potencia', {
    intent: 'product_search',
    message_role: session.product_id ? 'changes_order' : 'answers_pending_field',
    answers_pending_field: pending === 'produto',
    product_id: String(mentionedProduct.product_id),
    product_search_term: String(mentionedProduct.product_name),
    customer_terms: [text]
  });
}


// 4.9) Uma resposta numérica após uma lista escolhe a opção exibida.
// Ela nunca pode virar quantidade de um produto antigo.
const numericOptionMatch = text.match(/^\s*([1-9])\s*[.)-]?\s*$/);

if (numericOptionMatch) {
  const optionNumber = Number(numericOptionMatch[1]);
  const previousReply = String(
    session.last_bot_message ??
    session.lastBotMessage ??
    ''
  ).trim();

  const normalizedPreviousReply = normalize(previousReply);

  const previousReplyOfferedOptions =
    /\bqual\s+(?:opcao|delas|produto)\b/i.test(
      normalizedPreviousReply
    ) ||
    /\bqual\s+voce\s+(?:prefere|deseja)\b/i.test(
      normalizedPreviousReply
    );

  const listedProducts = products
    .map((product) => {
      const productName = String(
        product.product_name ??
        product.name ??
        product.title ??
        ''
      ).trim();

      const normalizedName = normalize(productName);

      return {
        product,
        productName,
        normalizedName,
        position: normalizedName
          ? normalizedPreviousReply.indexOf(normalizedName)
          : -1
      };
    })
    .filter((entry) =>
      entry.productName &&
      entry.position >= 0
    )
    .sort((left, right) =>
      left.position - right.position
    )
    .filter((entry, index, entries) => {
      const productId = String(
        entry.product.product_id ??
        entry.product.id ??
        ''
      );

      return entries.findIndex((candidate) =>
        String(
          candidate.product.product_id ??
          candidate.product.id ??
          ''
        ) === productId
      ) === index;
    });

  const chosenEntry = listedProducts[optionNumber - 1];

  if (previousReplyOfferedOptions && chosenEntry) {
    const chosenProduct = chosenEntry.product;
    const chosenProductId =
      chosenProduct.product_id ??
      chosenProduct.id ??
      null;

    return fast('selecao_numerada_lista_anterior', {
      intent: 'product_search',
      message_role: 'changes_order',
      answers_pending_field: true,
      product_id: chosenProductId,
      product_search_term: chosenEntry.productName,
      customer_terms: [chosenEntry.productName],
      selection_number: optionNumber,
      selection_resets_quantity: true
    });
  }
}

// 5) Quantidade só tem prioridade quando a mensagem realmente é uma quantidade. Perguntas interrompem a coleta.
// Aceita número isolado, número + unidade e números por extenso mais comuns.
const lastBotNormalized = normalize(session.last_bot_message ?? '');
const waitingForQuantity =
  pending === 'quantidade' ||
  (Boolean(session.product_id) && !Number(session.quantity ?? 0)) ||
  /quantas unidades|qual a quantidade|informe a quantidade/.test(lastBotNormalized);

// V25.4: aceita quantidade do jeito que uma pessoa realmente escreve:
// "3", "quero 3", "me vê 3", "3 unidades", "quero três".
const quantityText = n
  .replace(/^(?:quero|vou querer|pode ser|me ve|manda|separa|separe|vou levar|quero levar)\s+/, '')
  .trim();

const numericQuantity = quantityText.match(/^(\d{1,2})(?: unidades?| un| u| pecas?| produtos?| carregadores?)?$/);
const quantityByWord = ({
  'um': 1,
  'uma': 1,
  'um produto': 1,
  'um carregador': 1,
  'uma unidade': 1,
  'dois': 2,
  'duas': 2,
  'duas unidades': 2,
  'tres': 3,
  'tres unidades': 3,
  'quatro': 4,
  'cinco': 5
})[quantityText] ?? null;

const quantityCandidate = numericQuantity
  ? Number(numericQuantity[1])
  : quantityByWord;

if (
  waitingForQuantity &&
  Number.isInteger(quantityCandidate) &&
  quantityCandidate >= 1 &&
  quantityCandidate <= 20
) {
  return fast('quantidade_exata', {
    intent: 'order_data',
    message_role: 'answers_pending_field',
    answers_pending_field: true,
    quantity: quantityCandidate
  });
}

const broadQuestionDuringQuantity =
  /\?|\b(qual|quanto|como|porque|por que|serve|funciona|compativel|aplica|aplicacao|adequado|apropriado|diferenca|comparar|garantia|original|cabo|entrada|potencia)\b/.test(n);

if (waitingForQuantity && broadQuestionDuringQuantity) {
  return useAi('pergunta_durante_coleta_de_quantidade');
}

// Enquanto faltar quantidade, evita aceitar outros dados fora de ordem,
// mas somente quando a mensagem não for uma pergunta.
if (waitingForQuantity) {
  return fast('aguardando_quantidade', {
    reply: 'Quantas unidades você deseja? Responda somente com o número, por exemplo: 1.',
    intent: 'order_data',
    message_role: 'other',
    answers_pending_field: false
  });
}

if (pending === 'pagamento') {
  if (/^(pix|pelo pix|no pix)$/.test(n)) {
    return fast('pagamento_pix', {
      intent: 'order_data',
      message_role: 'answers_pending_field',
      answers_pending_field: true,
      payment_method: 'pix'
    });
  }

  if (/^(dinheiro|dinheiro na entrega|em dinheiro|pago em dinheiro)$/.test(n)) {
    return fast('pagamento_dinheiro', {
      intent: 'order_data',
      message_role: 'answers_pending_field',
      answers_pending_field: true,
      payment_method: 'cash'
    });
  }
}

// V25.6 — BAIRRO EXTRAÍDO DE FRASE NATURAL.
// Ex.: "Consegue entregar pra mim na Cremação?" -> "Cremação".
if (pending === 'bairro') {
  const extractedNeighborhood = extractNeighborhoodFromDelivery(text);
  const deliveryCue = /\b(entrega|entregar|frete|bairro|taxa|na|no|em|pra|para|pro)\b/.test(n);

  if (extractedNeighborhood && deliveryCue) {
    return fast('bairro_extraido_de_frase', {
      intent: 'order_data',
      message_role: 'answers_pending_field',
      answers_pending_field: true,
      neighborhood: extractedNeighborhood
    });
  }
}

const looksLikeQuestion =
  /\?/.test(text) ||
  /^(?:tem|qual|quanto|como|quando|onde|porque|por que|serve|funciona|pode|voces|vocês|vcs|deixa eu perguntar|posso perguntar|tenho uma duvida|tenho uma dúvida|uma pergunta|so uma pergunta|só uma pergunta)\b/i.test(text) ||
  standaloneDeviceModel;
const reservedShort = /^(sim|nao|não|ok|certo|beleza|blz|pix|dinheiro|confirmar|cancelar|novo pedido|67w|120w)$/i.test(n);
const commercialOrProductSentence =
  /\b(?:quero|vou querer|nao quero|nao vou querer|comprar|carregador|produto|trocar|troca|mudar|muda|separar|reservar|cancelar|garantia|serve|funciona|compativel|diferenca|comparar|perguntar|duvida|celular|aparelho|samsung|sansung|galaxy|xiaomi|redmi|poco|motorola|moto|iphone|realme)\b/.test(n) ||
  /\b(?:67|120)\s*w\b/.test(n) ||
  standaloneDeviceModel;

if (pending === 'nome' && !looksLikeQuestion && !reservedShort && !commercialOrProductSentence) {
  const looksLikeName = /^[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ' -]{1,59}$/.test(text) && text.split(/\s+/).length <= 6;
  if (looksLikeName) {
    return fast('nome_recebedor', {
      intent: 'order_data',
      message_role: 'answers_pending_field',
      answers_pending_field: true,
      customer_name: text
    });
  }
}

if (pending === 'bairro' && !looksLikeQuestion && !reservedShort && !commercialOrProductSentence) {
  const looksLikeNeighborhood = /^[A-Za-zÀ-ÿ0-9][A-Za-zÀ-ÿ0-9 .'ºª-]{1,59}$/.test(text);
  if (looksLikeNeighborhood) {
    return fast('bairro_entrega', {
      intent: 'order_data',
      message_role: 'answers_pending_field',
      answers_pending_field: true,
      neighborhood: cleanNeighborhood(text) ?? text
    });
  }
}

if (pending === 'endereço' && !looksLikeQuestion && !reservedShort && !commercialOrProductSentence) {
  const addressCue = /\b(rua|avenida|av|travessa|tv|passagem|alameda|rodovia|estrada|conjunto|residencial|numero|número|nº|quadra|lote|casa|bloco|apto|apartamento)\b/i.test(text);
  const hasNumber = /\d/.test(text);
  if (text.length >= 5 && text.length <= 180 && (addressCue || hasNumber)) {
    return fast('endereco_entrega', {
      intent: 'order_data',
      message_role: 'answers_pending_field',
      answers_pending_field: true,
      address: text
    });
  }
}

return useAi('mensagem_complexa_ou_ambigua');

const route = $input.first().json;
const ai = route.fast_ai;

if (!ai || typeof ai !== 'object') {
  throw new Error('Rota rápida sem fast_ai estruturado.');
}

return [{
  json: {
    output_text: JSON.stringify(ai),
    fast_route: true,
    fast_route_reason: route.fast_route_reason ?? 'nao_informado',
    model: 'deterministic-local'
  }
}];

const raw = $input.first().json ?? {};

const decodeStream = value => {
  if (!value || typeof value !== 'object') return value;
  const buffer = value?._readableState?.buffer;
  const chunks = Array.isArray(buffer)
    ? buffer
    : Array.isArray(buffer?.head?.data)
      ? [buffer.head.data]
      : [];

  if (!chunks.length) return value;

  try {
    const bytes = chunks.flatMap(chunk => {
      if (Array.isArray(chunk)) return chunk;
      if (Array.isArray(chunk?.data)) return chunk.data;
      return [];
    });
    const text = Buffer.from(bytes).toString('utf8').trim();
    return text ? JSON.parse(text) : value;
  } catch {
    return value;
  }
};

const decoded = decodeStream(raw);
const rows = Array.isArray(decoded)
  ? decoded
  : Array.isArray(decoded?.data)
    ? decoded.data
    : decoded?.customer_number
      ? [decoded]
      : [];

const expected = $('Resposta Pedido Criado').first().json;
const expectedNumber = String(expected?.state?.order_number ?? '');
const row = rows[0] ?? null;
const savedStatus = String(row?.status ?? '').toLowerCase();
const savedNumber = String(row?.order_number ?? '');

if (!row) {
  throw new Error('SESSAO_CONFIRMADA_NAO_RETORNOU_REGISTRO');
}

if (!['reserved', 'confirmed'].includes(savedStatus)) {
  throw new Error(`SESSAO_CONFIRMADA_STATUS_INVALIDO:${savedStatus || 'vazio'}`);
}

if (expectedNumber && savedNumber !== expectedNumber) {
  throw new Error(`SESSAO_CONFIRMADA_NUMERO_DIVERGENTE:${savedNumber || 'vazio'}`);
}

return [{
  json: {
    ...expected,
    confirmationPersisted: true,
    persistedSession: row
  }
}];

const raw = $input.first().json ?? {};

let base;

if ($('Aplicar Taxa do Supabase').isExecuted) {
  base = $('Aplicar Taxa do Supabase').first().json;
} else if ($('Manter Inteligência da v16').isExecuted) {
  base = $('Manter Inteligência da v16').first().json;
} else if ($('Confirmar Cancelamento do Pedido').isExecuted) {
  base = $('Confirmar Cancelamento do Pedido').first().json;
} else {
  base = $('Consolidar Sessão').first().json;
}


// ======================================================
// DECODIFICA RESPOSTAS BUFFER / STREAM
// ======================================================

const decodeBufferLike = value => {
  if (!value || typeof value !== 'object') return value;

  const candidates = [
    value?._readableState?.buffer,
    value?.body?._readableState?.buffer,
    value?.data?._readableState?.buffer
  ].filter(Boolean);

  for (const buffer of candidates) {
    const chunks = [];

    if (Array.isArray(buffer)) {
      chunks.push(...buffer);
    } else if (buffer?.head) {
      let cursor = buffer.head;
      let safety = 0;

      while (cursor && safety++ < 1000) {
        chunks.push(cursor.data ?? cursor);
        cursor = cursor.next;
      }
    }

    const bytes = [];

    for (const chunk of chunks) {
      const data =
        Array.isArray(chunk) ? chunk :
        Array.isArray(chunk?.data) ? chunk.data :
        Array.isArray(chunk?.chunk?.data) ? chunk.chunk.data :
        Array.isArray(chunk?.buffer?.data) ? chunk.buffer.data :
        null;

      if (data) {
        bytes.push(...data);
      }
    }

    if (bytes.length) {
      try {
        const text = Buffer
          .from(bytes)
          .toString('utf8')
          .trim();

        if (text) {
          return JSON.parse(text);
        }
      } catch {}
    }
  }

  return value;
};


// ======================================================
// LOCALIZA REGISTROS DE SESSÃO NO RETORNO
// ======================================================

const collectRows = (
  value,
  rows = [],
  seen = new Set(),
  depth = 0
) => {
  if (
    depth > 20 ||
    value === null ||
    value === undefined
  ) {
    return rows;
  }

  const decoded = decodeBufferLike(value);

  if (decoded !== value) {
    return collectRows(
      decoded,
      rows,
      seen,
      depth + 1
    );
  }

  if (typeof value !== 'object') {
    return rows;
  }

  if (seen.has(value)) {
    return rows;
  }

  seen.add(value);

  if (Array.isArray(value)) {
    for (const item of value) {
      collectRows(
        item,
        rows,
        seen,
        depth + 1
      );
    }

    return rows;
  }

  if (value.customer_number) {
    rows.push(value);
  }

  for (const child of Object.values(value)) {
    collectRows(
      child,
      rows,
      seen,
      depth + 1
    );
  }

  return rows;
};


