  // ------------------------------------------------------
  if (masterStatus === 'RESOLVED') {
    const device = deviceMasterResolution.device ?? {};
    const recommended = deviceMasterResolution.recommended_product ?? null;
    const resolvedProducts = Array.isArray(deviceMasterResolution.products)
      ? deviceMasterResolution.products
      : [];

    const availableResolvedProducts = resolvedProducts
      .filter(product =>
        product &&
        product.product_id &&
        Number(product.available_quantity ?? 0) > 0
      )
      .slice(0, 8);

    compatibility.compatible_products = availableResolvedProducts.map(product => ({
      product_id: product.product_id,
      product_name: product.product_name ?? null,
      sale_price: product.sale_price ?? null,
      power_watts: product.power_watts ?? null,
      connector_type: product.connector_type ?? device.connector_type ?? null,
      available_quantity: product.available_quantity ?? 0,
      approved_answer: product.approved_answer ?? null
    }));
    compatibility.device_official_max_watts = device.official_max_watts ?? null;
    compatibility.device_model_id =
      deviceMasterResolution.device_model_id ?? device.device_model_id ?? null;

    // Se o cliente já escolheu um produto no checkout, testa ESSE produto.
    // Não troca 120W por 67W silenciosamente só porque 67W é a recomendação comercial.
    const selectedProductId = session.product_id ?? null;
    const selectedCompatibleProduct = selectedProductId
      ? resolvedProducts.find(p => String(p?.product_id ?? '') === String(selectedProductId)) ?? null
      : null;

    const deviceLimit =
      Number(device.official_max_watts ?? 0);

    // Recomendação prática:
    // escolhe a menor potência compatível que seja suficiente
    // para o limite oficial do aparelho.
    const sufficientProducts =
      deviceLimit > 0
        ? availableResolvedProducts
            .filter(product => {
              const watts =
                Number(product?.power_watts ?? 0);

              return watts >= deviceLimit;
            })
            .sort((left, right) => {
              const leftWatts =
                Number(left?.power_watts ?? 0);
              const rightWatts =
                Number(right?.power_watts ?? 0);

              const powerDifference =
                leftWatts - rightWatts;

              if (powerDifference !== 0) {
                return powerDifference;
              }

              return (
                Number(
                  left?.sale_price ??
                    Number.MAX_SAFE_INTEGER
                ) -
                Number(
                  right?.sale_price ??
                    Number.MAX_SAFE_INTEGER
                )
              );
            })
        : [];

    const practicalProduct =
      sufficientProducts[0] ??
      recommended ??
      availableResolvedProducts[0] ??
      null;

    const effectiveProduct =
      selectedCompatibleProduct ??
      practicalProduct;

    if (effectiveProduct && effectiveProduct.product_id) {
      compatibility.found = true;
      compatibility.device = [device.brand, device.model]
        .filter(Boolean)
        .join(' ')
        .trim() || null;
      compatibility.device_brand = device.brand ?? null;
      compatibility.device_model = device.model ?? null;
      compatibility.device_connector = device.connector_type ?? effectiveProduct.connector_type ?? null;
      const asksRecommendation =
        /\b(turbo|mais\s+rapido|bem\s+rapido|rapido|veloz|melhor|mais\s+potente|potente)\b/
          .test(currentNormalized);

      const approvedAnswer = String(effectiveProduct.approved_answer ?? '').trim();
      const deviceLabel = [device.brand, device.model].filter(Boolean).join(' ').trim();
      const productLabel = String(effectiveProduct.product_name ?? '').trim();
      const productPrice = effectiveProduct.sale_price;

      const hasMultipleCompatibleOptions =
        availableResolvedProducts.length > 1;
      const safeTechnicalNote = deviceLimit > 0
        ? `O aparelho aceita até ${deviceLimit}W e controla automaticamente a potência recebida. A velocidade máxima depende do padrão reconhecido pelo aparelho e do cabo.`
        : 'O próprio aparelho controla automaticamente a potência recebida. A velocidade máxima depende do padrão reconhecido e do cabo.';

      compatibility.answer = selectedCompatibleProduct
        ? approvedAnswer
        : hasMultipleCompatibleOptions && productLabel
          ? (
              `Para o ${deviceLabel || 'seu aparelho'}, a opção mais equilibrada é o ${productLabel}` +
              (productPrice !== null && productPrice !== undefined
                ? ` por R$ ${money(productPrice)}`
                : '') +
              `. ${safeTechnicalNote} Quer 1 unidade?`
            )
          : asksRecommendation && productLabel
            ? (
                `Para o ${deviceLabel || 'seu aparelho'}, eu indicaria o ${productLabel}` +
                (productPrice !== null && productPrice !== undefined
                  ? ` por R$ ${money(productPrice)}`
                  : '') +
                `. ${approvedAnswer || safeTechnicalNote} Quer 1 unidade?`
              )
            : approvedAnswer;

      compatibility.product_id = effectiveProduct.product_id ?? null;
      compatibility.device_model_id =
        deviceMasterResolution.device_model_id ?? device.device_model_id ?? null;
      compatibility.recommended_product = effectiveProduct;
      compatibility.commercial_recommended_product = recommended;
      compatibility.selected_product_preserved = Boolean(selectedCompatibleProduct);
      compatibility.source = 'base_mestre_rpc_v1_2';
      compatibility.session_status = 'confirmed';
    }
  }

  // ------------------------------------------------------
  // BASE MESTRE: CANDIDATO PRÓXIMO ÚNICO
  // Nunca autocorrige. Guarda o candidato como memória pendente
  // para que "sim / isso / é esse" possa confirmá-lo no próximo turno.
  // ------------------------------------------------------
  else if (masterStatus === 'NEEDS_CONFIRMATION') {
    const candidate =
      deviceMasterResolution.suggested_device ??
      (Array.isArray(deviceMasterResolution.candidates)
        ? deviceMasterResolution.candidates[0]
        : null) ??
      {};

    const candidateLabel = [candidate.brand, candidate.model]
      .filter(Boolean)
      .join(' ')
      .trim();

    const informed = String(deviceMasterResolution.input ?? currentText ?? '').trim();

    compatibility.found = false;
    compatibility.device_brand = candidate.brand ?? null;
    compatibility.device_model = candidate.model ?? null;
    compatibility.device = candidateLabel || null;
    compatibility.device_connector = candidate.connector_type ?? null;
    compatibility.device_model_id = candidate.device_model_id ?? null;
    compatibility.pending_candidate_device_model_id = candidate.device_model_id ?? null;
    compatibility.pending_candidate_score = candidate.score ?? null;
    compatibility.source = 'base_mestre_near_match_v1_2';
    compatibility.session_status = 'needs_confirmation';
    compatibility.candidates = candidateLabel ? [candidate] : [];
    compatibility.answer = candidateLabel
      ? `Só para confirmar: você informou "${informed}". Você quis dizer ${candidateLabel}?`
      : 'Encontrei um aparelho muito parecido, mas preciso confirmar o modelo exato antes de indicar o carregador.';
  }

  // ------------------------------------------------------
  // BASE MESTRE: VARIANTE AMBÍGUA
  // ------------------------------------------------------
  else if (masterStatus === 'AMBIGUOUS') {
    const resolution = deviceMasterResolution.resolution ?? {};
    const candidates = Array.isArray(resolution.candidates)
      ? resolution.candidates.slice(0, 5)
      : [];

    const models = [...new Set(
      candidates
        .map(candidate => String(candidate?.model ?? '').trim())
        .filter(Boolean)
    )];

    const brands = [...new Set(
      candidates
        .map(candidate => String(candidate?.brand ?? '').trim())
        .filter(Boolean)
    )];

    compatibility.found = false;
    compatibility.device_brand = brands.length === 1 ? brands[0] : (compatibility.device_brand ?? null);
    compatibility.device_model = null;
    compatibility.device = null;
    compatibility.source = 'base_mestre_ambiguous';
    compatibility.session_status = 'needs_confirmation';
    compatibility.candidates = candidates;
    compatibility.answer = models.length >= 2
      ? `Encontrei mais de uma versão desse aparelho: ${models.join(' e ')}. Qual dessas versões é a sua?`
      : 'Encontrei mais de uma versão desse aparelho. Me diga a versão exata para eu confirmar a compatibilidade.';
  }

  // ------------------------------------------------------
  // BASE MESTRE: NÃO CADASTRADO
  // O próprio RPC já registrou na fila de não resolvidos.
  // ------------------------------------------------------
  else if (masterStatus === 'NOT_FOUND') {
    compatibility.found = false;
    compatibility.source = 'base_mestre_not_found';
    compatibility.session_status = 'needs_confirmation';
    compatibility.answer =
      'Ainda não tenho esse modelo confirmado na nossa base técnica. Me envie o nome exato que aparece em Configurações > Sobre o telefone, ou uma foto dessa tela, para eu verificar sem arriscar uma informação errada.';
  }

  // ------------------------------------------------------
  // FALLBACK LEGADO
  // Só é usado quando a Base Mestre foi pulada/indisponível.
  // ------------------------------------------------------
  else {
    const mentionedWatts = Number(currentNormalized.match(/\b(20|67|120)\s*w\b/)?.[1] ?? 0);

  const rankedMatches = catalog
    .map(item => {
      const brand = normalize(item.brand);
      const model = normalize(item.model);
      const aliases = Array.isArray(item.aliases)
        ? item.aliases.map(normalize).filter(Boolean)
        : [];

      if (!model) return null;

      const brandMatch = Boolean(brand && contextText.includes(brand));
      const modelCoreTokens = model
        .split(' ')
        .filter(token => token.length >= 2 && /\d/.test(token));
      const coreHits = modelCoreTokens
        .filter(token => contextText.includes(token))
        .length;

      let score = brandMatch ? 20 : 0;

      // Modelo completo/alias completo tem prioridade máxima.
      if (contextText.includes(model)) score = Math.max(score, 105);
      for (const alias of aliases) {
        if (alias && contextText.includes(alias)) score = Math.max(score, 115);
      }

      // Não permite que somente a palavra "Samsung" selecione um aparelho aleatório.
      if (modelCoreTokens.length && coreHits === modelCoreTokens.length) {
        score = Math.max(score, brandMatch ? 100 : 85);
      } else if (coreHits > 0) {
        score = Math.max(score, (brandMatch ? 20 : 0) + coreHits * 35);
      }

      const product = products.find(p => String(p.product_id ?? '') === String(item.product_id ?? ''));
      const productWatts = Number(product?.power_watts ?? 0);
      if (mentionedWatts && productWatts === mentionedWatts) score += 20;

      const commercialRank =
        productWatts === 67 ? 0 :
        productWatts === 120 ? 1 :
        2;

      return { item, score, commercialRank };
    })
    .filter(Boolean)
    .filter(x => x.score >= 55)
    .sort((a, b) =>
      (b.score - a.score) ||
      (a.commercialRank - b.commercialRank)
    );

  const match = rankedMatches[0]?.item ?? null;

  if (match) {
    compatibility.found = true;
    compatibility.device = [match.brand, match.model]
      .filter(Boolean)
      .join(' ')
      .trim();
    compatibility.device_brand = match.brand ?? null;
    compatibility.device_model = match.model ?? null;
    compatibility.device_connector = match.connector_type ?? null;
    compatibility.answer = String(match.approved_answer ?? '').trim();
    compatibility.product_id = match.product_id ?? null;
    compatibility.source = 'approved_compatibility_catalog';
    compatibility.session_status = 'confirmed';
  }

  // V25.5 — fallback comercial estritamente baseado no CATÁLOGO OFICIAL.
  // O iPhone 13/13 Pro informado pelo cliente não pode cair no loop de "mande foto"
  // quando existe, no próprio catálogo, um carregador explicitamente destinado a iPhone.
  if (!compatibility.found && /\biphone\s*13(?:\s*(?:mini|pro(?:\s*max)?))?\b/.test(contextText)) {
    const iphoneProduct = products.find(product => {
      if (Number(product.available_quantity ?? 0) <= 0) return false;

      const productText = normalize([
        product.product_name,
        product.product_slug,
        product.description,
        product.connector_type,
        ...(Array.isArray(product.aliases) ? product.aliases : [])
      ].filter(Boolean).join(' '));

      const isForIphone = /\biphone\b/.test(productText);
      const isCharger = /\bcarregador\b/.test(productText);
      const hasFastCue =
        Number(product.power_watts ?? 0) >= 20 ||
        /\bcarregamento rapido\b|\bturbo\b/.test(productText);

      return isForIphone && isCharger && hasFastCue;
    });

    if (iphoneProduct) {
      const detectedModel =
        contextText.match(/\biphone\s*13(?:\s*(?:mini|pro(?:\s*max)?))?\b/)?.[0] ??
        'iPhone 13';

      const prettyModel = detectedModel
        .replace(/\biphone\b/i, 'iPhone')
        .replace(/\bpro\b/i, 'Pro')
        .replace(/\bmax\b/i, 'Max')
        .replace(/\bmini\b/i, 'mini');

      const cableText =
        iphoneProduct.cable_included === true
          ? `, já com cabo ${iphoneProduct.connector_type || 'compatível'} incluso`
          : '';

      compatibility.found = true;
      compatibility.device = prettyModel;
      compatibility.device_brand = 'Apple';
      compatibility.device_model = prettyModel;
      compatibility.device_connector = iphoneProduct.connector_type ?? 'Lightning';
      compatibility.answer =
        `Para o ${prettyModel}, temos o ${iphoneProduct.product_name} por R$ ${money(iphoneProduct.sale_price)}${cableText}. ` +
        `É a opção que temos para iPhone. Quer que eu separe uma unidade para você? 😊`;
      compatibility.source = 'official_product_catalog_iphone13';
      // O produto é oficialmente voltado para iPhone, mas a correspondência por modelo
      // veio do catálogo de produto (não da tabela específica de compatibilidade).
      compatibility.session_status = 'needs_confirmation';
      compatibility.product_id = iphoneProduct.product_id ?? null;
    }
  }
  }
}

// V25.6 — MEMÓRIA DO APARELHO MESMO QUANDO A BASE AINDA NÃO TEM O MODELO.
// Isso evita perguntar marca/modelo novamente. Não afirma compatibilidade.
if (compatibility.handled && !compatibility.found && !['AMBIGUOUS', 'NOT_FOUND', 'NEEDS_CONFIRMATION'].includes(masterStatus)) {
  const media = data.mediaAnalysis && typeof data.mediaAnalysis === 'object'
    ? data.mediaAnalysis
    : {};

  const knownBrands = [
    ['samsung', 'Samsung'],
    ['xiaomi', 'Xiaomi'],
    ['redmi', 'Xiaomi'],
    ['poco', 'Xiaomi'],
    ['motorola', 'Motorola'],
    ['moto', 'Motorola'],
    ['iphone', 'Apple'],
    ['apple', 'Apple'],
    ['realme', 'Realme'],
    ['oppo', 'Oppo'],
    ['infinix', 'Infinix'],
    ['tecno', 'Tecno'],
    ['asus', 'Asus'],
    ['zenfone', 'Asus'],
    ['lg', 'LG'],
    ['nokia', 'Nokia']
  ];

  let detectedBrand = String(media.device_brand ?? '').trim();
  let detectedModel = String(media.device_model ?? '').trim();

  if (!detectedBrand) {
    const brandHit = knownBrands.find(([token]) => contextText.includes(token));
    detectedBrand = brandHit?.[1] ?? '';
  }

  if (!detectedModel) {
    const rawContext = [currentText, quotedText]
      .filter(Boolean)
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim();

    const modelPatterns = [
      /\b(?:motorola\s+)?moto\s+g\s*\d{1,3}(?:\s*[45]g)?\b/i,
      /\b(?:samsung\s+)?(?:galaxy\s+)?[asmxg]\s*\d{1,3}(?:\s*[45]g)?\b/i,
      // V25.6.2: aceita ordem humana/errada: "A06 sansung".
      /\b[asmxg]\s*\d{1,3}(?:\s*[45]g)?\s+(?:samsung|sansung|galaxy)\b/i,
      /\b(?:redmi|poco|xiaomi)\s+[a-z0-9][a-z0-9 +._-]{1,35}\b/i,
      /\biphone\s*\d{1,2}(?:\s*(?:mini|pro(?:\s*max)?))?\b/i
    ];

    detectedModel = modelPatterns
      .map(pattern => rawContext.match(pattern)?.[0] ?? '')
      .find(Boolean) ?? '';
  }

  if (detectedBrand || detectedModel) {
    // Evita duplicar a marca no rótulo/modelo: "Motorola Motorola Moto G75 5G".
    if (detectedBrand && detectedModel) {
      const brandNorm = normalize(detectedBrand);
      const modelNorm = normalize(detectedModel);
      if (modelNorm.startsWith(brandNorm + ' ')) {
        const firstSpace = detectedModel.indexOf(' ');
        if (firstSpace >= 0) {
          detectedModel = detectedModel.slice(firstSpace + 1).trim();
        }
      }
    }

    compatibility.device_brand = detectedBrand || compatibility.device_brand || null;
    compatibility.device_model = detectedModel || compatibility.device_model || null;

    const brandNorm = normalize(compatibility.device_brand);
    const modelNorm = normalize(compatibility.device_model);
    compatibility.device = modelNorm && brandNorm && modelNorm.startsWith(brandNorm + ' ')
      ? String(compatibility.device_model).trim()
      : [compatibility.device_brand, compatibility.device_model]
          .filter(Boolean)
          .join(' ')
          .trim() || null;

    compatibility.session_status = 'needs_confirmation';
    compatibility.source = 'customer_device_context';
  }
}

// ======================================================
// V25.8 — SAÍDA ENXUTA DO COMPATIBILITY ENGINE
// Não repassa a base inteira para os próximos nós.
// ======================================================

const fullCatalog = Array.isArray(data.compatibilityCatalog)
  ? data.compatibilityCatalog
  : [];

// Se encontramos o aparelho, mantém somente registros
// referentes ao aparelho identificado.
let relevantCompatibilityCatalog = [];

if (compatibility.found) {
  const detectedBrand = normalize(compatibility.device_brand);
  const detectedModel = normalize(compatibility.device_model);

  relevantCompatibilityCatalog = fullCatalog
    .filter(item => {
      const brand = normalize(item?.brand);
      const model = normalize(item?.model);

      return (
        (!detectedBrand || brand === detectedBrand) &&
        (!detectedModel || model === detectedModel)
      );
    })
    .slice(0, 6);
}

// Se não encontrou correspondência exata, tenta manter
// apenas alguns registros relacionados ao texto atual.
if (!relevantCompatibilityCatalog.length) {
  relevantCompatibilityCatalog = fullCatalog
    .map(item => {
      const brand = normalize(item?.brand);
      const model = normalize(item?.model);

      const aliases = Array.isArray(item?.aliases)
        ? item.aliases.map(normalize).filter(Boolean)
        : [];

      let score = 0;

      if (brand && contextText.includes(brand)) {
        score += 20;
      }

      if (model && contextText.includes(model)) {
        score += 100;
      }

      for (const alias of aliases) {
        if (alias && contextText.includes(alias)) {
          score = Math.max(score, 110);
        }
      }

      return {
        item,
        score
      };
    })
    .filter(result => result.score >= 20)
    .sort((a, b) => b.score - a.score)
    .slice(0, 6)
    .map(result => result.item);
}


// ======================================================
// SANITIZA SESSÃO
// ======================================================

const safeSession = {
  ...session
};

const oldBotMessage = String(
  safeSession.last_bot_message ?? ''
).trim();

if (oldBotMessage.length > 900) {
  safeSession.last_bot_message =
    'Resposta anterior extensa omitida para controle de contexto.';
}

const oldCustomerMessage = String(
  safeSession.last_customer_message ?? ''
).trim();

if (oldCustomerMessage.length > 1800) {
  safeSession.last_customer_message =
    oldCustomerMessage.slice(-1800);
}


// ======================================================
// REMOVE CAMPOS PESADOS ANTES DE REPASSAR
// ======================================================

const {
  compatibilityCatalog: _fullCompatibilityCatalog,
  catalog_debug,
  compatibility_debug,
  ...safeData
} = data;


// ======================================================
// OUTPUT
// ======================================================

return [{
  json: {
    ...safeData,

    // V25.6.3 — repassa ao classificador o catálogo já enriquecido.
    products,

    session: safeSession,

    compatibility,

    // Agora o próximo nó recebe no máximo 6 registros,
    // nunca a base completa.
    compatibilityCatalog: relevantCompatibilityCatalog,

    compatibilityCatalogOriginalCount: fullCatalog.length,
    compatibilityCatalogSentCount: relevantCompatibilityCatalog.length,

    compatibilityPayloadSanitized: true
  }
}];

const raw = $input.first().json ?? {};
const base = $('Cancelar pedido confirmado?').first().json;
const state = { ...(base.state ?? {}) };

const apiStatus = String(
  raw?.data?.status ??
  raw?.status ??
  ''
).toLowerCase();

const errorCode = String(
  raw?.error?.code ??
  raw?.data?.error?.code ??
  raw?.body?.error?.code ??
  ''
).toUpperCase();

const errorMessage = String(
  raw?.error?.message ??
  raw?.data?.error?.message ??
  raw?.message ??
  ''
).trim();

const success =
  raw?.success === true ||
  apiStatus === 'cancelled';

const orderNumber = String(base.cancelOrderNumber ?? state.order_number ?? '').trim();
const orderLabel = orderNumber ? ` nº ${orderNumber}` : '';
const startNewAfterCancel = base.startNewAfterCancel === true;

const humanState = {
  human_takeover: Boolean(state.human_takeover),
  human_takeover_at: state.human_takeover_at ?? null,
  human_takeover_by: state.human_takeover_by ?? null,
  automation_paused_until: state.automation_paused_until ?? null
};

const buildCleanState = (status, reply) => ({
  customer_number: state.customer_number ?? base.number,
  customer_name: state.customer_name ?? null,
  product_key: null,
  product_id: null,
  product_name: null,
  unit_price: null,
  inventory_id: null,
  quantity: null,
  neighborhood: null,
  address: null,
  reference: null,
  payment_method: null,
  delivery_fee: null,
  products_total: 0,
  price_source: 'sale_price',
  learned_terms: [],
  status,
  last_customer_message: String(base.text ?? state.last_customer_message ?? '').trim(),
  last_bot_message: reply,
  order_id: null,
  order_number: null,
  ...humanState,
  updated_at: new Date().toISOString()
});

// V25.3 — reconciliação de sessão órfã.
// Se o pedido foi apagado no painel, a API responde ORDER_NOT_FOUND. Nesse caso,
// não faz sentido manter order_id/status antigos na sessão do WhatsApp.
if (!success && errorCode === 'ORDER_NOT_FOUND') {
  const reply = startNewAfterCancel
    ? `Esse pedido${orderLabel} já não está mais ativo no sistema. Limpei o vínculo antigo por aqui. Vamos começar um novo pedido — o que você quer levar?`
    : `Esse pedido${orderLabel} já não está mais ativo no sistema. Limpei o vínculo antigo por aqui. Se quiser fazer outro pedido, é só me dizer o que você precisa.`;

  const cleanState = buildCleanState('collecting', reply);

  return [{
    json: {
      ...base,
      state: cleanState,
      reply,
      createOrder: false,
      cancelConfirmedOrder: false,
      staleOrderReconciled: true,
      orderCancellationCompleted: true,
      isNewOrder: startNewAfterCancel,
      postOrderHandled: true
    }
  }];
}

if (!success) {
  const previousStatus = String(base.cancelOrderPreviousStatus ?? state.status ?? 'ativo').toLowerCase();
  const statusLabels = {
    reserved: 'reservado',
    confirmed: 'confirmado',
    preparing: 'em preparação',
    dispatched: 'em rota de entrega',
    delivered: 'entregue',
    cancelled: 'cancelado'
  };
  const previousStatusLabel = statusLabels[previousStatus] ?? previousStatus;
  const detail = errorMessage ? ` (${errorMessage})` : '';
  const reply =
    `Não consegui concluir o cancelamento do pedido${orderLabel} automaticamente agora${detail}. ` +
    `Por segurança, ele continua como ${previousStatusLabel} até eu receber a confirmação do sistema.`;

  state.last_customer_message = String(base.text ?? state.last_customer_message ?? '').trim();
  state.last_bot_message = reply;
  state.updated_at = new Date().toISOString();

  return [{
    json: {
      ...base,
      state,
      reply,
      createOrder: false,
      cancelConfirmedOrder: false,
      cancellationFailed: true,
      postOrderHandled: true
    }
  }];
}

const reply = startNewAfterCancel
  ? `Pedido${orderLabel} cancelado com sucesso. ✅ Vamos começar outro pedido — o que você quer levar?`
  : `Pedido${orderLabel} cancelado com sucesso. ✅ Se precisar de outra coisa, é só chamar.`;

const cancelledState = buildCleanState(
  startNewAfterCancel ? 'collecting' : 'cancelled',
  reply
);

return [{
  json: {
    ...base,
    state: cancelledState,
    reply,
    createOrder: false,
    cancelConfirmedOrder: false,
    orderCancellationCompleted: true,
    isNewOrder: startNewAfterCancel,
    postOrderHandled: true
  }
}];

// V25.4 — restaura o contexto que existia antes do DELETE da sessão.
// O DELETE serve apenas para remover a linha conversacional antiga e impedir
// que uma proteção de sessão finalizada ressuscite order_id/order_number antigos.
let source = null;

if (
  $('Confirmar Cancelamento do Pedido').isExecuted &&
  $('Confirmar Cancelamento do Pedido').first().json
) {
  source = $('Confirmar Cancelamento do Pedido').first().json;
} else {
  source = $('Reiniciar sessão para novo pedido?').first().json;
}

if (!source || typeof source !== 'object') {
  throw new Error('CONTEXTO_NAO_ENCONTRADO_APOS_LIMPEZA_DA_SESSAO');
}

return [{
  json: {
    ...source,
    sessionRowHardReset: true
  }
}];

const data = $input.first().json;

const text = String(
  data.text ??
  data.message ??
  $('Configuração Geral1').first().json.text ??
  ''
).trim();

const sessionCandidates = $('Buscar Sessão').all().flatMap(item => {
  const value = item?.json;
  if (Array.isArray(value)) return value;
  if (Array.isArray(value?.data)) return value.data;
  if (value && typeof value === 'object') return [value];
  return [];
});

const session =
  data.session && typeof data.session === 'object'
    ? data.session
    : (sessionCandidates[0] ?? {});

const media =
  data.mediaAnalysis && typeof data.mediaAnalysis === 'object'
    ? data.mediaAnalysis
    : {};

const normalize = value =>
  String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

const n = normalize(text);

// V25.6.3 — prioriza código oficial Samsung informado pelo cliente.
// Ex.: A156M, A156/M/DSN e SM-A156M/DSN.
const samsungCodeMatch = n.match(/\b(?:sm[\s\/-]*)?([asm][\s\/-]*\d{3}[\s\/-]*[a-z])(?:[\s\/-]*(dsn))?\b/);
const officialDeviceCode = samsungCodeMatch
  ? `SM-${samsungCodeMatch[1].replace(/[\s\/-]+/g, "").toUpperCase()}${samsungCodeMatch[2] ? "/DSN" : ""}`
  : null;

let detectedBrand = null;
let detectedModel = null;

// -----------------------------
// MARCA — somente da mensagem atual
// A Base Mestre será a autoridade final.
// -----------------------------
if (/\b(samsung|sansung|samsumg|samgung|galaxy)\b/.test(n)) {
  detectedBrand = 'Samsung';
}
else if (/\b(motorola|moto)\b/.test(n)) {
  detectedBrand = 'Motorola';
}
else if (/\b(xiaomi|xiomi|xaomi|redmi|poco)\b/.test(n)) {
  detectedBrand = 'Xiaomi';
}
else if (/\b(iphone|apple)\b/.test(n)) {
  detectedBrand = 'Apple';
}
else if (/\brealme\b/.test(n)) {
  detectedBrand = 'Realme';
}
else if (/\boppo\b/.test(n)) {
  detectedBrand = 'Oppo';
}
else if (/\binfinix\b/.test(n)) {
  detectedBrand = 'Infinix';
}
else if (/\btecno\b/.test(n)) {
  detectedBrand = 'Tecno';
}
else if (/\b(asus|zenfone)\b/.test(n)) {
  detectedBrand = 'Asus';
}
else if (/\blg\b/.test(n)) {
  detectedBrand = 'LG';
}
else if (/\bnokia\b/.test(n)) {
  detectedBrand = 'Nokia';
}

// -----------------------------
// MODELO — somente da mensagem atual
// O regex só extrai um candidato; quem resolve variante é o Supabase.
// -----------------------------
let m = n.match(
  /\b(?:samsung|sansung|samsumg|samgung|galaxy)?\s*((?:a|s|m|f)\s*\d{1,3}(?:\s*(?:ultra|plus|fe))?(?:\s*[45]g)?)\b/
);

if (m) {
  detectedModel = m[1]
    .replace(/\s+/g, ' ')
    .replace(/^([asmf])\s+/i, '$1')
    .trim();
}

if (!detectedModel) {
  m = n.match(
    /\b(?:motorola\s+)?((?:moto\s+)?(?:g|e)\s*\d{1,3}(?:\s*(?:plus|power|play|stylus))?(?:\s*5g)?|edge\s*\d{1,3}(?:\s*(?:pro|fusion|neo|ultra))?)\b/
  );
  if (m) detectedModel = m[1].replace(/\s+/g, ' ').trim();
}

if (!detectedModel) {
  m = n.match(
    /\b((?:redmi\s+note|redmi|poco)\s+[a-z0-9]+(?:\s+[a-z0-9]+){0,3})\b/
  );
  if (m) detectedModel = m[1].replace(/\s+/g, ' ').trim();
}

if (!detectedModel) {
  m = n.match(
    /\b(iphone\s+\d{1,2}(?:\s*(?:mini|plus|pro|pro max))?)\b/
  );
  if (m) detectedModel = m[1].replace(/\s+/g, ' ').trim();
}

if (!detectedModel) {
  m = n.match(/\b(realme\s+[a-z0-9]+(?:\s+[a-z0-9]+){0,3})\b/);
  if (m) detectedModel = m[1].replace(/^realme\s+/i, '').trim();
}

// V1.3 — modelos genéricos de marcas que não seguem família Samsung/Moto.
// Exemplos: OPPO A60, realme C55, Infinix Note 40, Tecno Pova 6.
// Captura somente a estrutura do modelo; a Base Mestre continua sendo a autoridade.
if (!detectedModel) {
  m = n.match(
    /\b(?:realme|oppo|infinix|tecno|asus|zenfone|lg|nokia)\s+((?:[a-z]{1,12}\s+)?[a-z]?\d{1,4}[a-z0-9]*(?:\s+(?:pro|plus|max|ultra|neo|5g|4g|pro\+))?)\b/
  );
  if (m) detectedModel = m[1].replace(/\s+/g, ' ').trim();
}

// Imagem analisada segue o MESMO resolver canônico.
// Só usa marca/modelo visual quando a análise realmente os forneceu.
if (!detectedBrand && media.device_brand) {
  detectedBrand = String(media.device_brand).trim() || null;
}

if (!detectedModel && media.device_model) {
  detectedModel = String(media.device_model).trim() || null;
}

const sessionBrand = session.device_brand ?? null;
const sessionModel = session.device_model ?? null;

const confirmationText = normalize(text);
const shortConfirmation = /^(?:s+i+m+|i+s+s+o+(?:\s+m+e+s+m+o+)?|e+s+s+e+(?:\s+m+e+s+m+o+)?|e+s+s+a+(?:\s+m+e+s+m+a+)?|e+\s+e+s+s+[ea]+|c+o+r+r+e+t+o+|e+x+a+t+o+|q+u+e+r+o+|p+o+d+e+\s+s+e+r+)$/.test(confirmationText);
const compatibilityLanguage = /\b(serve|funciona|compativel|compatível|carrega|carregar|usar|para meu|pro meu|no meu|modelo|celular|aparelho)\b/i.test(text);

// V1.3 — continuação comercial depois que o aparelho já foi informado.
// Ex.: "OPPO A60" -> "quero um turbo bem rápido".
const recommendationLanguage =
  /\b(turbo|mais\s+rapido|bem\s+rapido|rapido|veloz|melhor|mais\s+potente|potente)\b/i.test(n);

const previousBotNormalized = normalize(session.last_bot_message ?? '');
const previousBotRequestedDevice =
  /marca e modelo|qual celular|qual aparelho|modelo exato|qual e o modelo|qual é o modelo|com qual celular/.test(previousBotNormalized);

const hasCurrentDeviceCue = Boolean(detectedBrand || detectedModel);
const continuationWithStoredDevice =
  Boolean(sessionModel) &&
  (shortConfirmation || recommendationLanguage);

const shouldSearchCompatibility =
  hasCurrentDeviceCue ||
  compatibilityLanguage ||
  continuationWithStoredDevice;

const brand = detectedBrand ?? sessionBrand ?? null;
const model =
  detectedModel ??
  (continuationWithStoredDevice ? sessionModel : null) ??
  null;

// Quando a Eliana acabou de pedir marca/modelo, preserva a resposta RAW do cliente.
// Isso impede que um regex corte justamente o erro que o Near Match precisa enxergar
// (ex.: "iPhone 13 pro mex" virar silenciosamente "iPhone 13 Pro").
// V25.10.1 — só considera resposta direta quando o cliente
// realmente escreveu apenas o nome do aparelho.
// Perguntas como "tem carregador para Moto G84 5G?"
// devem usar marca e modelo já extraídos pelos regexes.
const looksLikeDeviceOnlyAnswer =
  !/[?]/.test(text) &&
  !/^(?:tem|t[eê]m|voc[eê]s têm|vcs têm|quero|preciso|procuro|serve|funciona|carrega|carregador|fonte|cabo)\b/i
    .test(n);

const directDeviceAnswer =
  previousBotRequestedDevice &&
  !shortConfirmation &&
  looksLikeDeviceOnlyAnswer &&
  text.split(/\s+/).filter(Boolean).length <= 12;

const contextualQueryInput = directDeviceAnswer
  ? text
  : (continuationWithStoredDevice && !hasCurrentDeviceCue
      ? [sessionBrand, sessionModel].filter(Boolean).join(" ").trim()
      : ([detectedBrand ?? (detectedModel ? sessionBrand : null), detectedModel]
          .filter(Boolean)
          .join(" ")
          .trim() || text));

const queryInput = shouldSearchCompatibility
  ? (officialDeviceCode || contextualQueryInput)
  : null;

return [{
  json: {
    ...data,
    compatibility_search: {
      enabled: shouldSearchCompatibility,
      brand,
      model,
      detected_brand: detectedBrand,
      detected_model: detectedModel,
      query_input: queryInput,
      known_brand_for_resolver: officialDeviceCode
        ? "Samsung"
        : (shortConfirmation && !hasCurrentDeviceCue ? sessionBrand : null),
      known_model_for_resolver: officialDeviceCode
        ? officialDeviceCode
        : (shortConfirmation && !hasCurrentDeviceCue ? sessionModel : null),
      source: 'base_mestre_v1_2'
    }
  }
}];

parameters.body:
={{ (() => {
  const cfg = $('Configuração Geral1').first().json;
  const formatted = $('✨ Formatar Resposta ao Cliente').first().json;

  const number = String(cfg.number ?? '').trim();
  const originalText = String(cfg.text ?? '').trim();

  const imageMatch = originalText.match(
    /https?:\/\/[^\s\]\)]+?\.(?:jpg|jpeg|png|webp)/i
  );

  if (!imageMatch) {
    throw new Error('IMAGEM_PRODUTO_NAO_ENCONTRADA_NO_PEDIDO');
  }

  const mediaUrl = imageMatch[0];
  const reply = String(
    formatted?.reply ??
    '✅ Recebemos seu pedido corretamente e vamos dar continuidade à entrega por aqui.'
  ).trim();

  const fileName =
    mediaUrl.split('/').pop()?.split('?')[0] || 'produto.jpg';

  let mimetype = 'image/jpeg';

  if (/\.png(?:\?|$)/i.test(mediaUrl)) {
    mimetype = 'image/png';
  } else if (/\.webp(?:\?|$)/i.test(mediaUrl)) {
    mimetype = 'image/webp';
  }

  return JSON.stringify({
    number,
    mediatype: 'image',
    mimetype,
    media: mediaUrl,
    fileName,
    caption: reply
  });
})() }}

parameters.jsCode:
const data = $json.body ?? $json;

const orderId = String(data.order_id ?? '').trim();
const status = String(data.status ?? '').trim();
const reason = String(data.reason ?? '').trim();

const messages = {
  confirmed: '✅ Seu pedido foi confirmado!\n\nEm breve vamos iniciar a preparação.',

  preparing: '📦 Seu pedido está em preparação!\n\nEstamos organizando tudo para a sua entrega.',

  dispatched: '🚚 Seu pedido saiu para entrega!\n\nNosso entregador já está a caminho do seu endereço.',

  delivered: '✅ Pedido entregue com sucesso!\n\nObrigado por comprar com a Miranda Express. 🙂'
};

const message = messages[status];

if (!message) {
  throw new Error(`STATUS_NAO_SUPORTADO: ${status}`);
}

return [{
  json: {
    order_id: orderId,
    status,
    reason,
    message,
    test_mode: true
  }
}];

const wantedId = $('Montar Mensagem de Status').first().json.order_id;

// A API pode retornar array direto, { data: [...] } ou { orders: [...] }
const input = $input.all().map(i => i.json);

let orders = [];

for (const item of input) {
  if (Array.isArray(item)) {
    orders.push(...item);
  } else if (Array.isArray(item?.data)) {
    orders.push(...item.data);
  } else if (Array.isArray(item?.orders)) {
    orders.push(...item.orders);
  } else if (item && item.id) {
    orders.push(item);
  }
}

const order = orders.find(o =>
  String(o.id ?? '').trim() === String(wantedId).trim()
);

if (!order) {
  throw new Error(`PEDIDO_NAO_ENCONTRADO: ${wantedId}`);
}

const customerName = String(
  order.customer_name_snapshot ??
  order.customer_name ??
  order.customer?.name ??
  ''
).trim();

const customerPhone = String(
  order.customer_phone_snapshot ??
  order.customer_phone ??
  order.phone ??
  order.customer?.phone ??
  ''
).replace(/\D/g, '');

const orderCode = String(
  order.order_number ??
  order.order_code ??
  order.code ??
  ''
).trim();

if (!customerPhone) {
  throw new Error(`TELEFONE_DO_CLIENTE_NAO_ENCONTRADO: ${wantedId}`);
}

return [{
  json: {
    order_id: order.id,
    order_code: orderCode,
    customer_name: customerName,
    customer_phone: customerPhone,
    current_status: order.status ?? '',
    neighborhood: order.neighborhood_snapshot ?? '',
    address: order.address_snapshot ?? '',
    total: order.total ?? 0,
    order
  }
}];

const pedido = $json;

const statusData =
  $("Montar Mensagem de Status").first().json;

const orderCode = String(
  pedido.order_code ?? ""
).trim();

const customerName = String(
  pedido.customer_name ?? ""
).trim();

let customerPhone = String(
  pedido.customer_phone ?? ""
).replace(/\D/g, "");

// Remove zeros indevidos antes do DDD.
customerPhone = customerPhone.replace(/^0+/, "");

// Adiciona o código do Brasil quando vier apenas DDD + número.
if (
  customerPhone.length === 10 ||
  customerPhone.length === 11
) {
  customerPhone = `55${customerPhone}`;
}

// O telefone final precisa estar no padrão brasileiro internacional.
if (!/^55\d{10,11}$/.test(customerPhone)) {
  throw new Error(
    `TELEFONE_DO_CLIENTE_INVALIDO: ${customerPhone}`
  );
}

const status = String(
  statusData.status ?? ""
).trim();

const firstName = customerName
  ? customerName.split(/\s+/)[0]
  : "cliente";

const messages = {
  confirmed:
`✅ Pedido confirmado!

Olá, ${firstName}. Seu pedido ${orderCode} foi confirmado com sucesso.

Em breve vamos iniciar a preparação.`,

  preparing:
`📦 Pedido em preparação!

Olá, ${firstName}. Seu pedido ${orderCode} já está sendo preparado.

Estamos organizando tudo para a sua entrega.`,

  dispatched:
`🚚 Seu pedido saiu para entrega!

Olá, ${firstName}. O pedido ${orderCode} já saiu para entrega.

Nosso entregador está a caminho do seu endereço.`,

  delivered:
`✅ Pedido entregue com sucesso!

Olá, ${firstName}. O pedido ${orderCode} foi marcado como entregue.

Obrigado por comprar com a Miranda Express. 🙂`
};

const text = messages[status];

if (!text) {
  throw new Error(
    `STATUS_SEM_MENSAGEM: ${status}`
  );
}

return [
  {
    json: {
      number: customerPhone,
      text,
      order_id: pedido.order_id,
      order_code: orderCode,
      status
    }
  }
];

const original = $('Configuração Geral1').first().json;
const raw = $input.first().json ?? {};

const base64 = String(
  raw.base64 ??
  raw.data?.base64 ??
  raw.response?.base64 ??
  ''
).replace(/^data:[^;]+;base64,/i, '').trim();

const mime = String(
  raw.mimetype ??
  raw.mimeType ??
  raw.data?.mimetype ??
  original.mediaMimeType ??
  'image/jpeg'
).trim();

const mediaReadyForVision = Boolean(base64 && /^image\//i.test(mime));

const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    image_kind: {
      type: 'string',
      enum: ['phone_box', 'phone_screen', 'charger', 'cable', 'receipt', 'document', 'other']
    },
    device_brand: { type: ['string', 'null'] },
    device_model: { type: ['string', 'null'] },
    visible_text: { type: 'string' },
    summary: { type: 'string' },
    confidence: { type: 'number', minimum: 0, maximum: 1 }
  },
  required: ['image_kind', 'device_brand', 'device_model', 'visible_text', 'summary', 'confidence']
};

return [{
  json: {
    ...original,
    mediaReadyForVision,
    downloadedMediaMimeType: mime,
    visionBody: mediaReadyForVision ? {
      model: original.visionModel || original.openaiModel || 'gpt-5-mini',
      store: false,
      max_output_tokens: 450,
      reasoning: { effort: 'minimal' },
      input: [{
        role: 'user',
        content: [
          {
            type: 'input_text',
            text:
              'Analise a imagem enviada por um cliente da Miranda Express. ' +
              'Leia texto visível e identifique, quando existir, a marca e o modelo exatos do celular. ' +
              'Se for caixa de celular, priorize o nome comercial do aparelho impresso na caixa. ' +
              'Não invente informação que não esteja visível. Se estiver incerto, use null e reduza confidence.'
          },
          {
            type: 'input_image',
            image_url: `data:${mime};base64,${base64}`,
            detail: 'high'
          }
        ]
      }],
      text: {
        verbosity: 'low',
        format: {
          type: 'json_schema',
          name: 'miranda_media_analysis',
          strict: true,
          schema
        }
      }
    } : null
  }
}];

const original = $('Configuração Geral1').first().json;
const raw = $input.first().json ?? {};

let outputText =
  raw.output_text ??
  (raw.output ?? [])
    .flatMap(o => o.content ?? [])
    .find(x => x.type === 'output_text')?.text ??
  '';

let analysis = null;
try {
  analysis = outputText ? JSON.parse(outputText) : null;
} catch {
  analysis = null;
}

if (!analysis || typeof analysis !== 'object') {
  analysis = {
    image_kind: 'other',
    device_brand: null,
    device_model: null,
    visible_text: '',
    summary: 'Imagem recebida, mas a análise automática não retornou dados estruturados.',
    confidence: 0
  };
}

const brand = String(analysis.device_brand ?? '').trim();
const model = String(analysis.device_model ?? '').trim();
const device = [brand, model].filter(Boolean).join(' ').trim();
const visible = String(analysis.visible_text ?? '').trim();
const summary = String(analysis.summary ?? '').trim();

const contextParts = [];
if (device) contextParts.push(`aparelho identificado: ${device}`);
if (analysis.image_kind) contextParts.push(`tipo da imagem: ${analysis.image_kind}`);
if (visible) contextParts.push(`texto visível: ${visible}`);
if (summary) contextParts.push(`resumo: ${summary}`);

const originalText = String(original.originalText ?? original.text ?? '').trim();
const visualSentence = contextParts.length
  ? `Imagem enviada pelo cliente (${contextParts.join('; ')}).`
  : 'Imagem enviada pelo cliente.';

return [{
  json: {
    ...original,
    originalText,
    text: [originalText, visualSentence].filter(Boolean).join(' '),
    mediaAnalysis: analysis,
    visionAnalyzed: true,
    visionConfidence: Number(analysis.confidence ?? 0)
  }
}];

const original = $('Configuração Geral1').first().json;
const originalText = String(original.originalText ?? original.text ?? '').trim();
const fallback = 'Imagem enviada pelo cliente. Não foi possível analisar automaticamente o conteúdo desta imagem.';
return [{
  json: {
    ...original,
    originalText,
    text: [originalText, fallback].filter(Boolean).join(' '),
    mediaAnalysis: {
      image_kind: 'other',
      device_brand: null,
      device_model: null,
      visible_text: '',
      summary: fallback,
      confidence: 0
    },
    visionAnalyzed: false,
    visionConfidence: 0
  }
}];

// V25.6.1 — PEDIDO DO SITE TEM PRIORIDADE ABSOLUTA.
// O pedido já foi criado pelo checkout da loja. Aqui NÃO criamos outro pedido
// e NÃO pedimos confirmação novamente. Apenas registramos a sessão correta
// e respondemos ao cliente.

const c = $('Configuração Geral1').first().json;
const text = String(c.text ?? '').trim();
const clean = text.replace(/\*/g, '');

const value = regex => {
  const m = clean.match(regex);
  return String(m?.[1] ?? '').trim() || null;
};

const moneyNumber = raw => {
  if (!raw) return null;
  const s = String(raw)
    .replace(/[^0-9,.-]/g, '')
    .replace(/\.(?=\d{3}(?:\D|$))/g, '')
    .replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

const orderNumber =
  c.siteOrderNumber ||
  value(/Fiz meu pedido pelo site\.\s*Pedido\s+([A-Z0-9-]+)/i) ||
  value(/Pedido:\s*([A-Z0-9-]+)/i);

if (!orderNumber) {
  throw new Error('PEDIDO_SITE_SEM_NUMERO');
}

const productName = value(/(?:^|\n)[^\n]*Produto:\s*([^\n]+)/i);
const quantityRaw = value(/(?:^|\n)[^\n]*Quantidade:\s*(\d+)/i);
const quantity = Math.max(1, Number(quantityRaw ?? 1) || 1);
const productsTotal = moneyNumber(value(/(?:^|\n)[^\n]*Valor dos produtos:\s*R?\$?\s*([^\n]+)/i));
const customerNameFromText = value(/(?:^|\n)[^\n]*Cliente:\s*([^\n]+)/i);
const address = value(/(?:^|\n)[^\n]*Endere[cç]o:\s*([^\n]+)/i);
const neighborhood = value(/(?:^|\n)[^\n]*Bairro:\s*([^\n]+)/i);
const referenceRaw = value(/(?:^|\n)[^\n]*Refer[eê]ncia:\s*([^\n]+)/i);
const phoneFromText = value(/(?:^|\n)[^\n]*WhatsApp:\s*([^\n]+)/i)?.replace(/\D/g, '') || null;
const device = value(/(?:^|\n)[^\n]*Celular:\s*([^\n]+)/i);
const deliveryFee = moneyNumber(value(/(?:^|\n)[^\n]*Taxa de entrega:\s*R?\$?\s*([^\n]+)/i));
const total = moneyNumber(value(/(?:^|\n)[^\n]*TOTAL:\s*R?\$?\s*([^\n]+)/i));
const paymentText = value(/(?:^|\n)[^\n]*Pagamento:\s*([^\n]+)/i) || '';
const paymentMethod = /pix/i.test(paymentText)
  ? 'pix'
  : /dinheiro/i.test(paymentText)
    ? 'cash'
    : null;

const reference =
  !referenceRaw || /n[aã]o informado/i.test(referenceRaw)
    ? null
    : referenceRaw;

const customerName =
  customerNameFromText ||
  (c.customerName && c.customerName !== 'Cliente' ? c.customerName : null);

const unitPrice =
  productsTotal !== null && quantity > 0
    ? Number((productsTotal / quantity).toFixed(2))
    : null;

const reply =
  `✅ Pedido ${orderNumber} recebido com sucesso!\n\n` +
  `${productName ? `${productName}${quantity ? ` — ${quantity} unidade${quantity > 1 ? 's' : ''}` : ''}\n` : ''}` +
  `${total !== null ? `Total: R$ ${total.toFixed(2).replace('.', ',')}\n\n` : '\n'}` +
  `Seu pedido já está registrado no sistema. Não precisa confirmar novamente. Vamos seguir com a entrega por aqui.`;

const state = {
  customer_number: String(c.number ?? ''),
  customer_name: customerName,
  product_key: null,
  product_id: null,
  product_name: productName,
  unit_price: unitPrice,
  inventory_id: null,
  quantity,
  neighborhood,
  address,
  reference,
  payment_method: paymentMethod,
  delivery_fee: deliveryFee,
  device_brand: null,
  device_model: device,
  device_connector: null,
  compatibility_status: 'unknown',
  learned_terms: [],
  status: 'reserved',
  order_id: null,
  order_number: orderNumber,
  last_customer_message: text,
  last_bot_message: reply,
  updated_at: new Date().toISOString()
};

return [{
  json: {
    ...c,
    state,
    reply,
    createOrder: false,
    confirm_order: false,
    siteOrderHandled: true,
    siteOrderNumber: orderNumber,
    siteOrderCustomerPhone: phoneFromText,
    siteOrderTotal: total,
    preserveCurrentReply: true
  }
}];

const base = $('Preparar Pedido do Site').first().json;
const raw = $input.first().json ?? {};

// Mesmo que o Supabase devolva uma representação vazia/stream,
// preserva a resposta determinística do pedido do site.
return [{
  json: {
    ...base,
    siteOrderSessionSaved: true,
    siteOrderSaveResponse: raw,
    createOrder: false,
    preserveCurrentReply: true
  }
}];

const source = $input.first().json ?? {};
const originalReply = String(source.reply ?? "").trim();

if (!originalReply) {
  throw new Error("RESPOSTA_VAZIA_NO_FORMATADOR");
}

const normalize = value =>
  String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();

const hasLeadingEmoji = value =>
  /^[\p{Extended_Pictographic}\uFE0F]/u.test(
    String(value ?? "").trim()
  );

const productEmoji = value => {
  const text = normalize(value);

  if (/\b(fone|airpods|tws|earbuds|bluetooth|ows)\b/.test(text)) {
    return "🎧";
  }

  if (/\b(cabo|usb|lightning|conector|tipo c|type c)\b/.test(text)) {
    return "🔌";
  }

  if (/\b(carregador|fonte|\d+\s*w|potencia|turbo)\b/.test(text)) {
    return "⚡";
  }

  return "📦";
};

const bulletEmoji = value => {
  const text = normalize(value);

  // Campos estruturados do resumo do pedido.
  if (/^(quantidade|qtd)\b/.test(text)) {
    return "🔢";
  }

  if (/^(bairro|endereco|referencia|local)\b/.test(text)) {
    return "📍";
  }

  if (/^(taxa de entrega|taxa|frete|entrega)\b/.test(text)) {
    return "🚚";
  }

  if (/^(pagamento|forma de pagamento)\b/.test(text)) {
    return "💳";
  }

  if (/^(produtos|subtotal|total|preco|valor)\b/.test(text)) {
    return "💰";
  }

  if (/^(numero|pedido|status)\b/.test(text)) {
    return "📦";
  }

  return productEmoji(value);
};

const lineEmoji = value => {
  const text = normalize(value);

  if (/\b(obrigad|por nada|disposicao|ate mais|bem vindo|bom dia|boa tarde|boa noite|ola|oi)\b/.test(text)) {
    return "😊";
  }

  // Localização tem prioridade sobre a entrega genérica.
  if (/\b(bairro|endereco|rua|avenida|travessa|passagem|conjunto|numero|referencia)\b/.test(text)) {
    return "📍";
  }

  if (/\b(entrega|entregamos|cidade|frete|taxa|motoboy|prazo)\b/.test(text)) {
    return "🚚";
  }

  if (/\b(garantia|troca|defeito|fabricacao|protecao)\b/.test(text)) {
    return "🛡️";
  }

  // Pagamento é diferente de preço.
  if (/\b(pix|dinheiro|pagamento|forma de pagamento|cartao)\b/.test(text)) {
    return "💳";
  }

  if (/\b(preco|valor|custa|r\$|subtotal|total)\b/.test(text)) {
    return "💰";
  }

  // Conectores têm prioridade sobre marcas e aparelhos citados.
  if (/\b(cabo|usb|usb c|lightning|conexao|conector|entrada|tipo c|type c)\b/.test(text)) {
    return "🔌";
  }

  if (/\b(iphone|samsung|motorola|xiaomi|realme|oppo|celular|aparelho|compativel|compatibilidade|modelo)\b/.test(text)) {
    return "📱";
  }

  if (/\b(estoque|disponivel|unidades|embalagem|acompanha|conteudo|pedido|reservado)\b/.test(text)) {
    return "📦";
  }

  if (/\b(carregador|fonte|potencia|\d+\s*w|turbo|carregamento)\b/.test(text)) {
    return "⚡";
  }

  if (/\b(confirmado|correto|perfeito|certo|recebemos|sucesso)\b/.test(text)) {
    return "✅";
  }

  if (/\b(nao temos|indisponivel|sem estoque|nao encontrado)\b/.test(text)) {
    return "❌";
  }

  if (/\b(atendente|pessoa|equipe|atendimento humano)\b/.test(text)) {
    return "👤";
  }

  return "💬";
};

const lines = originalReply.split("\n");
let previousWasBlank = true;

const formattedLines = lines.map(rawLine => {
  const line = String(rawLine ?? "");
  const trimmed = line.trim();

  if (!trimmed) {
    previousWasBlank = true;
    return "";
  }

  // Mantém links isolados sem prefixo.
  if (/^https?:\/\/\S+$/i.test(trimmed)) {
    previousWasBlank = false;
    return trimmed;
  }

  // Produtos em listas recebem o emoji da categoria.
  const bullet = trimmed.match(/^([*•-])\s+(.+)$/);

  if (bullet) {
    const content = bullet[2].trim();

    if (hasLeadingEmoji(content)) {
      previousWasBlank = false;
      return `• ${content}`;
    }

    previousWasBlank = false;
    return `• ${bulletEmoji(content)} ${content}`;
  }

  // Títulos de catálogo e resumo.
  if (/^(produtos disponiveis|opcoes disponiveis|resumo do pedido)\s*:/i.test(normalize(trimmed))) {
    previousWasBlank = false;
    return `📦 *${trimmed}*`;
  }

  if (hasLeadingEmoji(trimmed)) {
    previousWasBlank = false;
    return trimmed;
  }

  // Primeira linha de cada parágrafo recebe um indicador do assunto.
  if (previousWasBlank) {
    previousWasBlank = false;
    return `${lineEmoji(trimmed)} ${trimmed}`;
  }

  previousWasBlank = false;
  return trimmed;
});

let formattedReply = formattedLines
  .join("\n")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

// ======================================================
// V1.2 — divulgação contextual da loja online.
// O site serve para consultar catálogo, fotos,
// compatibilidade e reservar produtos.
// O pagamento continua sendo somente na entrega.
// ======================================================

const storeUrl = "https://loja.vectradev.shop";
const normalizedOriginalReply = normalize(originalReply);

const alreadyMentionsStore =
  originalReply.includes(storeUrl);

const orderConfirmed =
  /\bpedido confirmado com sucesso\b/.test(
    normalizedOriginalReply
  ) ||
  (
    /\bnumero\s*:\s*vc\b/.test(
      normalizedOriginalReply
    ) &&
    /\bstatus\s*:\s*(reservado|confirmado)\b/.test(
      normalizedOriginalReply
    )
  );

const checkoutCollection =
  /\bquantas unidades voce deseja\b/.test(
    normalizedOriginalReply
  ) ||
  /\bqual (?:e )?o bairro ou conjunto\b/.test(
    normalizedOriginalReply
  ) ||
  /\benvie o endereco completo\b/.test(
    normalizedOriginalReply
  ) ||
  /\bpagamento sera por pix ou dinheiro\b/.test(
    normalizedOriginalReply
  ) ||
  /\bresponda confirmar para finalizar\b/.test(
    normalizedOriginalReply
  ) ||
  /\bconfirma (?:esse|o) bairro\b/.test(
    normalizedOriginalReply
  );

// Proteção adicional: nunca divulga o site enquanto
// o cliente estiver preenchendo ou confirmando o pedido.
const blocksStoreDuringCheckout =
  checkoutCollection ||
  normalizedOriginalReply.includes(
    "quantas unidades"
  ) ||
  normalizedOriginalReply.includes(
    "bairro ou conjunto"
  ) ||
  normalizedOriginalReply.includes(
    "envie o endereco completo"
  ) ||
  normalizedOriginalReply.includes(
    "pagamento sera por"
  ) ||
  normalizedOriginalReply.includes(
    "responda confirmar"
  ) ||
  normalizedOriginalReply.includes(
    "confirmar para finalizar"
  ) ||
  normalizedOriginalReply.includes(
    "confira seu pedido"
  ) ||
  normalizedOriginalReply.includes(
    "confirma esse bairro"
  ) ||
  normalizedOriginalReply.includes(
    "confirma o bairro"
  );

const recommendationClosure =
  (
    /\bopcoes compativeis\b/.test(normalizedOriginalReply) &&
    /\bqual opcao voce prefere\b/.test(normalizedOriginalReply)
  ) ||
  (
    /\bencontrei mais de uma opcao\b/.test(normalizedOriginalReply) &&
    /\bqual delas voce deseja\b/.test(normalizedOriginalReply)
  ) ||
  /\bpara o seu aparelho, eu indicaria\b/.test(normalizedOriginalReply);

const customerRequestedStore = /\b(site|link|cat[aá]logo|foto|fotos|imagem|imagens|loja online|ver produtos|ver os produtos|reservar online|reservar pelo site)\b/i.test(
  String(source.text || source.originalText || "")
);

let siteMessageAdded = false;
let siteMessageReason = null;

// V26.2.2 — pedido explícito recebe somente o site oficial.
if (customerRequestedStore) {
  formattedReply =
    "🛍️ Aqui está o catálogo completo da Miranda Express, com fotos e produtos disponíveis:" +
    "\n🔗 " + storeUrl +
    "\n🚚 O pagamento é feito somente na entrega.";

  siteMessageAdded = true;
  siteMessageReason = "pedido_explicito_site";
} else if (customerRequestedStore &&
    !alreadyMentionsStore && orderConfirmed) {
  formattedReply +=
    "\n\n🛍️ Quando quiser reservar outro produto, acesse nossa loja online. Lá você encontra o catálogo completo, fotos e a consulta de compatibilidade com seu aparelho:" +
    "\n🔗 " + storeUrl +
    "\n🚚 O pagamento é feito somente no momento da entrega.";

  siteMessageAdded = true;
  siteMessageReason = "pedido_confirmado";
} else if (
  customerRequestedStore &&
    !alreadyMentionsStore &&
  recommendationClosure &&
  !blocksStoreDuringCheckout
) {
  formattedReply +=
    "\n\n🛍️ Se preferir, você também pode ver as fotos e reservar pelo site:" +
    "\n🔗 " + storeUrl +
    "\n🚚 Pagamento somente na entrega.";

  siteMessageAdded = true;
  siteMessageReason = "informacao_comercial";
}

return [{
  json: {
    ...source,
    reply: formattedReply,
    replyBeforeFormatting: originalReply,
    replyFormatted: true,
    replyFormatterVersion: "1.3",
    siteMessageAdded,
    siteMessageReason
  }
}];
